NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'II Chronicles'

CHAPTERS = {
    1: {
        1: 'Davidov sin Salomon je bil okrepljen v svojem kraljestvu in Gospod, njegov Bog, je bil z njim in ga silno poveličal.',
        2: 'Potem je Salomon spregovoril vsemu Izraelu, poveljnikom nad tisočimi, nad stotimi, sodnikom, vsakemu voditelju v vsem Izraelu in glavnim izmed očetov.',
        3: 'Tako je Salomon in vsa skupnost z njim, odšla k visokemu kraju, ki je bil pri Gibeónu, kajti tam je bilo šotorsko svetišče skupnosti Boga, ki ga je Gospodov služabnik Mojzes naredil v divjini.',
        4: 'Toda Božjo skrinjo je David prenesel gor iz Kirját Jearíma na kraj, ki ga je David pripravil zanjo, kajti zanjo je razpel šotor pri Jeruzalemu.',
        5: 'Poleg tega je bronast oltar, ki ga je naredil Becalél, Urijájev sin, Hurov sin, postavil pred Gospodovo šotorsko svetišče. Salomon in skupnost so povpraševali k njemu.',
        6: 'Salomon je odšel tja gor k bronastemu oltarju pred Gospoda, ki je bil pri šotorskem svetišču skupnosti in na njem daroval tisoč žgalnih daritev.',
        7: 'V tej noči se je Bog prikazal Salomonu in mu rekel: »Prosi, kaj naj ti dam.«',
        8: 'Salomon je Bogu rekel: »Veliko usmiljenje si pokazal mojemu očetu Davidu in mene si postavil, da kraljujem namesto njega.',
        9: 'Sedaj, oh Gospod Bog, naj bo utrjena tvoja obljuba mojemu očetu Davidu, kajti naredil si me za kralja nad ljudstvom, po množici podobnega zemeljskemu prahu.',
        10: 'Daj mi torej modrost in znanje, da lahko grem ven in stopim pred ljudstvo, kajti kdo lahko sodi to tvoje ljudstvo, ki je tako veliko?«',
        11: 'Bog je rekel Salomonu: »Ker je bilo to na tvojem srcu in nisi prosil bogastev, premoženja ali časti, niti življenja svojih sovražnikov, niti nisi prosil dolgega življenja, temveč si zase prosil modrost in znanje, da lahko sodiš mojemu ljudstvu, nad katerim sem te postavil za kralja,',
        12: 'sta ti modrost in znanje zagotovljena, jaz pa ti bom dal bogastva, premoženje in čast, takšno, kakršne nihče izmed kraljev, ki so bili pred teboj, ni imel niti ne bo nobeden za teboj imel podobne.«',
        13: 'Potem je Salomon prišel iz svojega potovanja k visokemu kraju, izpred šotorskega svetišča skupnosti, ki je bil pri Gibeónu, v Jeruzalem in kraljeval nad Izraelom.',
        14: 'Salomon je zbral bojne vozove in konjenike. Imel je tisoč štiristo bojnih vozov in dvanajst tisoč konjenikov, ki jih je namestil v mestih za bojne vozove in s kraljem v Jeruzalemu.',
        15: 'Kralj je storil, [da je bilo] srebra in zlata v Jeruzalemu zaradi obilja tako veliko, kakor kamenja in cedrova drevesa je naredil [tako številna] kakor je egiptovskih smokev, ki so v dolini.',
        16: 'Salomon je imel konje, privedene iz Egipta in laneno prejo. Kraljevi trgovci so laneno prejo prejeli za ceno.',
        17: 'Poslali so in iz Egipta pripeljali bojni voz za šeststo šeklov srebra in konja za sto petdeset in tako so privedli konje za vse kralje Hetejcev in za sirske kralje, po njihovih namenih.',
    },
    2: {
        1: 'Salomon se je odločil, da zgradi hišo za Gospodovo ime in hišo za svoje kraljestvo.',
        2: 'Salomon je naročil sedemdeset tisoč možem, da nosijo bremena in osemdeset tisočim, da sekajo na gori in tri tisoč šeststotim, da jih nadzorujejo.',
        3: 'Salomon je poslal k tirskemu kralju Hurámu, rekoč: »Kakor si ti postopal z mojim očetom Davidom in si mu poslal cedre, da mu zgradijo hišo, da prebiva v njej, celo tako postopaj z menoj.',
        4: 'Glej, gradim hišo imenu Gospoda, svojega Boga, da mu jo posvetim in da pred njim zažigam dišeče kadilo in za neprestane hlebe navzočnosti, za žgalne daritve zjutraj in zvečer, na šabate, na mlaje in na slovesne praznike Gospoda, našega Boga. To je odredba za Izraela na veke.',
        5: 'Hiša, ki jo gradim, je velika, kajti velik je naš Bog nad vsemi bogovi.',
        6: 'Toda kdo mu je zmožen zgraditi hišo, glede na to, da ga nebo in nebesa nebes ne morejo obseči? Kdo sem potem jaz, da bi mu zgradil hišo, razen da pred njim zažigam daritev?',
        7: 'Pošlji mi torej sedaj človeka, spretnega za delo v zlatu, v srebru, v bronu, v železu, v vijolični, v karmezinu in modri in da lahko vešče rezbari z veščimi možmi, ki so z menoj v Judeji in v Jeruzalemu, ki jih je priskrbel moj oče David.',
        8: 'Pošlji mi tudi cedrovino, cipresovino in sandalovino iz Libanona, kajti vem, da tvoji služabniki lahko vešče sekajo les na Libanonu in glej, moji služabniki bodo s tvojimi služabniki,',
        9: 'celo, da mi pripravijo lesa v obilju, kajti hiša, ki jo nameravam zgraditi, bo čudovito velika.',
        10: 'Glej, tvojim služabnikom, sekalcem, ki sekajo les, bom dajal dvajset tisoč mer zmlete pšenice, dvajset tisoč mer ječmena, dvajset tisoč čebrov vina in dvajset tisoč čebrov olja.«',
        11: 'Potem je tirski kralj Hurám odgovoril v pisanju, ki ga je poslal Salomonu: ›Ker Gospod ljubi svoje ljudstvo, te je naredil kralja nad njimi.‹',
        12: 'Poleg tega je Hurám rekel: »Blagoslovljen bodi Gospod, Izraelov Bog, ki je naredil nebo in zemljo, ki je kralju Davidu dal modrega sina, opremljenega z razumnostjo in razumevanjem, da lahko gradi hišo za Gospoda in hišo za svoje kraljestvo.',
        13: '§ Sedaj pošiljam spretnega moža, opremljenega z razumevanjem, od mojega očeta Huráma,',
        14: 'sina ženske izmed Danovih hčera, njegov oče pa je bil človek iz Tira, vešč, da dela v zlatu, srebru, bronu, železu, kamnu, lesu, vijoličnem, modrem, tankem lanenem platnu in v karmezinu. Tudi da gravira vsako vrsto graviranja in da spozna vsako napravo, ki bo postavljena k njemu, s tvojimi spretnimi ljudmi in s spretnimi ljudmi mojega gospoda Davida, tvojega očeta.',
        15: 'Zdaj naj torej pšenico, ječmen in vino, o katerem je govoril moj gospod, pošlje svojim služabnikom,',
        16: 'mi pa bomo sekali les iz Libanona, kolikor ga boš potreboval in ga k tebi spravili na splavih po morju v Jopo, ti pa ga boš odpeljal gor v Jeruzalem.«',
        17: 'Salomon je preštel vse tujce, ki so bili v deželi Izrael, po štetju, s katerim jih je preštel njegov oče David in najdenih je bilo sto triinpetdeset tisoč šeststo.',
        18: 'Sedemdeset tisoč izmed njih je postavil, da bodo nosilci bremen in osemdeset tisoč, da bodo sekalci na gori in tri tisoč šeststo nadzornikov, da ljudstvu pripravljajo delo.',
    },
    3: {
        1: 'Potem je Salomon začel graditi Gospodovo hišo v Jeruzalemu na gori Moríja, kjer se je Gospod prikazal njegovemu očetu Davidu, na kraju, ki ga je David pripravil – na mlatišču Jebusejca Ornana.',
        2: 'Začel je graditi drugi dan drugega meseca v četrtem letu svojega kraljevanja.',
        3: 'Torej to so stvari, v katerih je bil Salomon poučen za gradnjo Božje hiše. Dolžina po komolcih, po prvi meri, je bila šestdeset komolcev in širina dvajset komolcev.',
        4: 'Preddverje, ki je bilo pred hišo, dolžina tega je bila glede na širino hiše, dvajset komolcev in višina je bila sto dvajset. Znotraj je bila prevlečena s čistim zlatom.',
        5: 'Večjo hišo je obložil s cipresovino, jo prevlekel s čistim zlatom in na njej oblikoval palmova drevesa in verižice.',
        6: 'Hišo je zaradi lepote olepšal z dragocenimi kamni in zlato je bilo zlato iz Parvájima.',
        7: 'Z zlatom je prevlekel tudi hišo, bruna, podboje, njihove zidove in njihova vrata in na stene je vrezal kerube.',
        8: 'Naredil je najsvetejšo hišo, katere dolžina je bila glede na širino hiše, dvajset komolcev in njena širina dvajset komolcev in prevlekel jo je s čistim zlatom, kar znese šeststo talentov.',
        9: 'Teža žebljev je bila petdeset šeklov zlata. In gornje sobe je prevlekel z zlatom.',
        10: 'V najsvetejši hiši je naredil dva keruba iz rezbarskega dela in ju prevlekel z zlatom.',
        11: 'Peruti kerubov so bile dolge dvajset komolcev. Ena perut enega keruba je imela pet komolcev, segajoč do stene hiše in druga perut je prav tako imela pet komolcev, segajoč do peruti drugega keruba.',
        12: 'Ena perut drugega keruba je imela pet komolcev in je segala do stene hiše in druga perut je tudi imela pet komolcev in se dotikala peruti drugega keruba.',
        13: 'Peruti teh kerubov so se [v širino] razprostirala dvajset komolcev. Stala sta na njunih stopalih in njuna obraza sta bila [obrnjena] navznoter.',
        14: 'Naredil je zagrinjalo iz modre, vijolične, karmezina in tankega lanenega platna ter na njem oblikoval kerube.',
        15: 'Prav tako je pred hišo naredil dva stebra, visoka petintrideset komolcev in kapitel, ki je bil na vrhu vsakega izmed njih, je meril pet komolcev.',
        16: 'Naredil je verižice kakor v oraklju in jih pritrdil na glave stebrov in naredil sto granatnih jabolk ter jih pritrdil na verižice.',
        17: 'Pred templjem je vzdignil stebra, enega na desnici, drugega pa na levici. Ime tega na desnici je imenoval Jahín, ime tistega na levici pa Boaz.',
    },
    4: {
        1: 'Poleg tega je naredil oltar iz brona, dvajset komolcev dolg, dvajset komolcev širok in deset komolcev visok.',
        2: 'Prav tako je naredil ulito morje desetih komolcev od roba do roba, okroglo naokoli in pet komolcev je bila njegova višina in vrvica tridesetih komolcev ga je obdajala naokoli.',
        3: 'Pod tem je bila podobnost volov, ki so ga obdajali naokoli. Deset na komolec, obdajajoč morje naokoli. Dve vrsti volov sta bili uliti, ko je bilo to ulito.',
        4: 'Stalo je na dvanajstih volih, trije so gledali proti severu, trije so gledali proti zahodu, trije so gledali proti jugu in trije so gledali proti vzhodu. Morje je bilo postavljeno zgoraj nad njimi in vsi njihovi zadnji deli so bili [obrnjeni] navznoter.',
        5: 'Njegova debelina je bila širina dlani in njegov rob, podoben robu čaše, s cvetovi lilij in ta je sprejel in držal tri tisoč čebrov.',
        6: 'Naredil je tudi deset [okroglih] umivalnikov in pet jih je položil na levo roko, pet pa na desno, da so se umivali v njih. Takšne stvari, kot so jih darovali za žgalno daritev, so umivali v njih, toda morje je bilo, da so se v njem umivali duhovniki.',
        7: 'Naredil je deset svečnikov iz zlata glede na njihovo obliko in jih postavil v templju, pet na desni roki in pet na levi.',
        8: 'Naredil je tudi deset miz in jih postavil v templju, pet na desni strani in pet na levi. Naredil je sto umivalnikov iz zlata.',
        9: 'Nadalje je naredil dvor duhovnikov in velik dvor in vrata za dvor in jih prevlekel z bronom.',
        10: 'Morje je postavil na desni strani vzhodnega konca, nasproti jugu.',
        11: 'Hurám je naredil lonce, lopate in umivalnike. Hurám je končal delo, ki ga je imel za opraviti za kralja Salomona za Božjo hišo:',
        12: 'namreč dva stebra in zaobljena glaviča in kapitele, ki so bili na vrhu dveh stebrov; dve mreži, da pokrijeta dva zaobljena glaviča kapitelov, ki so bili na vrhu stebrov;',
        13: 'štiristo granatnih jabolk na dveh mrežah; dve vrsti granatnih jabolk na vsakem vencu, da pokrijeta dva zaobljena glaviča kapitelov, ki sta bila na stebrih.',
        14: 'Naredil je tudi podstavke in na podstavkih je naredil [okrogle] umivalnike.',
        15: 'Eno morje in dvanajst volov pod njim.',
        16: 'Tudi lonce, lopate, kavlje za meso in vse njihove priprave je Hirám, njegov oče, pripravil za kralja Salomona za Gospodovo hišo iz svetlega brona.',
        17: 'Na jordanski ravnini jih je kralj ulil, v ilovnati zemlji med Sukótom in Cerédo.',
        18: 'Tako je Salomon naredil vseh teh posod v velikem obilju, kajti teže brona niso mogli ugotoviti.',
        19: 'Salomon je naredil vse te posode, ki so bile za Božjo hišo, tudi zlati oltar in mize, na katerih so bili postavljeni hlebi navzočnosti,',
        20: 'poleg tega svečnike s svojimi svetilkami, ki naj bi po navadi gorele pred orakljem iz čistega zlata,',
        21: 'cvetove, svetilke in utrinjače, narejene iz zlata in to popolnega zlata,',
        22: 'utrinjala, umivalnike, žlice in kadilnice iz čistega zlata. Vhod hiše, njegova notranja vrata za najsvetejši prostor in vrata hiše templja, so bila iz zlata.',
    },
    5: {
        1: 'Tako je bilo vse delo, ki ga je Salomon naredil za Gospodovo hišo, končano. Salomon je prinesel noter vse stvari, ki jih je njegov oče David posvetil: srebro, zlato in vse priprave je položil med zaklade Božje hiše.',
        2: 'Potem je Salomon zbral Izraelove starešine in vse poglavarje rodov, vodilne izmed očetov Izraelovih otrok v Jeruzalem, da prenesejo gor skrinjo Gospodove zaveze iz Davidovega mesta, ki je Sion.',
        3: 'Zato so se vsi možje iz Izraela zbrali skupaj h kralju na prazniku, ki je bil v sedmem mesecu.',
        4: 'Prišli so vsi starešine Izraela in Lévijevci so dvignili skrinjo.',
        5: 'Skrinjo so prinesli gor, šotorsko svetišče skupnosti in vse svete posode, ki so bile v šotorskem svetišču, te so duhovniki in Lévijevci prinesli gor.',
        6: 'Tudi kralj Salomon in vsa Izraelova skupnost, ki so bili zbrani k njemu pred skrinjo, so žrtvovali ovce in vole, ki jih zaradi množice ni bilo mogoče prešteti.',
        7: 'Duhovniki so prinesli skrinjo Gospodove zaveze na njen kraj, k oraklju hiše, v najsvetejši kraj, celo pod peruti kerubov.',
        8: 'Kajti keruba sta svoje peruti razširjala nad prostorom skrinje in keruba sta od zgoraj pokrivala skrinjo in njena drogova.',
        9: 'Iz skrinje so izvlekli drogova, da sta bila konca drogov vidna od skrinje pred orakljem, toda od zunaj nista bila vidna. In tam je to do današnjega dne.',
        10: 'V skrinji ni bilo ničesar razen dveh tabel, ki ju je Mojzes položil vanjo pri Horebu, ko je Gospod sklenil zavezo z Izraelovimi otroki, ko so prišli iz Egipta.',
        11: 'In pripetilo se je, ko so duhovniki prišli iz svetega kraja (kajti vsi duhovniki, ki so bili prisotni, so bili posvečeni in takrat niso potem čakali po skupini.',
        12: 'Tudi Lévijevci, ki so bili pevci, vsi izmed njih od Asáfa, Hemána in Jedutúna, z njihovimi sinovi in njihovimi brati, ki so bili oblečeni v belo platno ter imeli cimbale, plunke in harfe, so stali na vzhodnem koncu oltarja in z njimi sto dvajset duhovnikov, ki so trobili s trobentami.)',
        13: 'Zgodilo se je celo, ko so bili trobentači in pevci kakor eno, da naredijo en zvok, da se ga sliši v hvaljenju in zahvaljevanju Gospodu, in ko so povzdignili svoj glas s trobentami, cimbalami in glasbenimi instrumenti ter hvalili Gospoda, rekoč: »Ker je dober, kajti njegovo usmiljenje traja večno,« da je bila potem hiša, napolnjena z oblakom, torej Gospodova hiša,',
        14: 'tako da duhovniki zaradi oblaka niso mogli stati, da bi služili, kajti Gospodova slava je napolnila Božjo hišo.',
    },
    6: {
        1: 'Potem je Salomon rekel: » Gospod je rekel, da bo prebival v gosti temi.',
        2: 'Toda jaz sem zate zgradil hišo prebivališča in prostor za tvoje prebivanje na veke.«',
        3: 'Kralj je obrnil svoj obraz in blagoslovil celotno Izraelovo skupnost in celotna Izraelova skupnost je stala.',
        4: 'Rekel je: »Blagoslovljen bodi Gospod, Izraelov Bog, ki je s svojimi rokami izpolnil to, kar je s svojimi usti govoril mojemu očetu Davidu, rekoč:',
        5: '›Od dneva, ko sem svoje ljudstvo privedel iz egiptovske dežele, nisem izbral nobenega mesta med vsemi Izraelovimi rodovi, da bi v njem zgradil hišo, da bi bilo tam lahko moje ime niti nisem izbral nobenega človeka, da bi bil vladar nad mojim ljudstvom Izraelom,',
        6: 'toda izbral sem Jeruzalem, da bo tam lahko moje ime in izbral sem Davida, da bo nad mojim ljudstvom Izraelom.‹',
        7: 'Torej, to je bilo na srcu mojega očeta Davida, da zgradi hišo za ime Gospoda, Izraelovega Boga.',
        8: 'Toda Gospod je mojemu očetu Davidu rekel: ›Ker je bilo to na tvojem srcu, da zgradiš hišo za moje ime, si storil dobro v tem, da je bilo to na tvojem srcu,',
        9: 'vendar hiše ne boš gradil ti, temveč tvoj sin, ki bo izšel iz tvojih ledij, on bo zgradil hišo za moje ime.‹',
        10: 'Gospod je torej izpolnil svojo besedo, ki jo je govoril, kajti vzdignjen sem na mesto svojega očeta Davida in postavljen sem na Izraelov prestol, kakor je obljubil Gospod in zgradil sem hišo za ime Gospoda, Izraelovega Boga.',
        11: 'Vanjo sem položil skrinjo, v kateri je Gospodova zaveza, ki jo je sklenil z Izraelovimi otroki.«',
        12: 'Stal je pred Gospodovim oltarjem v prisotnosti vse Izraelove skupnosti in razprostrl svoji roki,',
        13: 'kajti Salomon je naredil bronast oder, pet komolcev dolg, pet komolcev širok in tri komolce visok ter ga postavil v sredo dvora. Na njem je stal in pokleknil na svoja kolena pred vso Izraelovo skupnostjo in svoji roki razprostrl proti nebu',
        14: 'in rekel: »Oh Gospod, Izraelov Bog, tebi ni podobnega Boga ne v nebesih, ne na zemlji, ki se držiš zaveze in izkazuješ usmiljenje svojim služabnikom, ki z vsemi svojimi srci hodijo pred teboj.',
        15: 'Ti, ki si ohranil svojemu služabniku Davidu, mojemu očetu, to, kar si mu obljubil in govoriš s svojimi usti in si to izpolnil s svojo roko, kakor je to danes.',
        16: 'Zdaj torej, oh Gospod, Izraelov Bog, ohrani svojemu služabniku Davidu, mojemu očetu, to, kar si mu obljubil, rekoč: ›Ne bo ti zmanjkalo moža v mojem pogledu, da sedi na Izraelovem prestolu, vendar tako, da bodo tvoji otroci pazili na svojo pot, da hodijo po moji postavi, kakor si ti hodil pred menoj.',
        17: 'Sedaj torej, oh Gospod, Izraelov Bog, naj bo tvoja beseda, ki si jo govoril svojemu služabniku Davidu, podprta.',
        18: 'Toda mar bo Bog zagotovo prebival z ljudmi na zemlji? Glej, nebo in nebesa nebes te ne morejo vsebovati, kako veliko manj ta hiša, ki sem jo zgradil!',
        19: 'Ozri se na molitev svojega služabnika in k njegovi ponižni prošnji, oh Gospod, moj Bog, da prisluhneš joku in molitvi, ki jo tvoj služabnik moli pred teboj,',
        20: 'da bodo tvoje oči lahko odprte nad to hišo podnevi in ponoči, na kraju, o katerem si rekel, da boš tam položil svoje ime, da prisluhneš molitvi, ki jo tvoj služabnik moli proti temu kraju.',
        21: 'Prisluhni torej ponižnim prošnjam svojega služabnika in svojega ljudstva Izraela, ki jih bodo naredili proti temu kraju. Poslušaj iz svojega prebivališča, celó iz nebes in ko slišiš, odpusti.',
        22: 'Če človek greši zoper svojega bližnjega in je prisega položena nanj, ki ga primora priseči in prisega pride pred tvoj oltar v tej hiši,',
        23: 'potem poslušaj iz nebes, stori in sodi [med] svojima služabnikoma s povračilom zlobnemu, tako da položiš njegovo pot na njegovo lastno glavo in opravičiš pravičnega, tako da mu daš glede na njegovo pravičnost.',
        24: 'Če bo tvoje ljudstvo Izrael poraženo pred sovražnikom, ker so grešili zoper tebe in se bo vrnilo ter priznalo tvoje ime in molilo in naredilo ponižno prošnjo pred teboj v tej hiši,',
        25: 'tedaj prisluhni iz nebes in odpusti greh svojega ljudstva Izraela ter jih ponovno privedi v deželo, ki si jo dal njim in njihovim očetom.',
        26: 'Ko je nebo zaprto in ni dežja, ker so grešili zoper tebe; vendar če molijo proti temu kraju in priznajo tvoje ime in se odvrnejo od svojega greha, ko si jih prizadel,',
        27: 'potem poslušaj iz nebes in odpusti greh svojih služabnikov in svojega ljudstva Izraela, ko si jih učil dobre poti, po kateri naj bi hodili in pošlji dež na svojo deželo, ki si jo dal svojemu ljudstvu za dediščino.',
        28: 'Če bo v deželi pomanjkanje, kužna bolezen, če bo kvarjenje ali plesen, leteče kobilice ali gosenice, če jih njihovi sovražniki oblegajo v mestih njihove dežele, kakršenkoli udarec ali kakršnakoli bolezen bo tam,',
        29: 'potem kakršnakoli molitev ali kakršnakoli ponižna prošnja bo narejena od kateregakoli človeka ali od vsega tvojega ljudstva Izraela, ko bo vsak spoznal svoj lastni udarec in svojo lastno bolečino in bo razprostrl svoji roki v tej hiši,',
        30: 'tedaj prisluhni iz nebes, svojega prebivališča, odpusti in povrni vsakemu človeku glede na njegove lastne poti, katerega srce ti poznaš (kajti samo ti poznaš srca človeških otrok),',
        31: 'da se te bodo lahko bali, da hodijo po tvojih poteh tako dolgo, dokler živijo v deželi, ki si jo dal našim očetom.',
        32: 'Poleg tega glede tujca, ki ni iz tvojega ljudstva Izraela, temveč je prišel iz daljne dežele zaradi tvojega velikega imena, tvoje mogočne roke in tvojega iztegnjenega lakta; če pridejo in molijo v tej hiši,',
        33: 'tedaj prisluhni iz nebes, celó iz svojega prebivališča in stôri glede na vse, za kar tujec kliče k tebi, da bo vse ljudstvo zemlje poznalo tvoje ime in se te balo kakor tvoje ljudstvo Izrael in bo lahko vedelo, da je ta hiša, ki sem jo zgradil, imenovana po tvojem imenu.',
        34: 'Če gre tvoje ljudstvo na vojno zoper svoje sovražnike po poti, po kateri jih boš poslal in molijo k tebi obrnjeni k temu mestu, ki si ga izbral in k hiši, ki sem jo zgradil za tvoje ime,',
        35: 'tedaj prisluhni iz nebes njihovi molitvi in njihovim ponižnim prošnjam ter obravnavaj njihov primer.',
        36: 'Če grešijo zoper tebe (kajti nobenega človeka ni, ki ne greši) in si jezen nad njimi in jih izročiš pred njihove sovražnike in jih oni ujete odvedejo v deželo daleč proč ali blizu,',
        37: 'vendar če si premislijo v deželi, kamor so odvedeni ujetniki in se obrnejo in molijo k tebi v deželi svojega ujetništva, rekoč: ›Grešili smo, napačno smo storili in počeli zlobno;‹',
        38: 'če se vrnejo k tebi z vsem svojim srcem in z vso svojo dušo, v deželi svojega ujetništva, kamor so jih odvedli ujete in molijo k njihovi deželi, ki si jo dal njihovim očetom in k mestu, ki si ga izbral in k hiši, ki sem jo zgradil za tvoje ime,',
        39: 'tedaj prisluhni iz nebes, celó iz svojega prebivališča, njihovi molitvi in njihovim ponižnim prošnjam in obravnavaj njihov primer in odpusti svojemu ljudstvu, ki je grešilo zoper tebe.',
        40: 'Sedaj, moj Bog, naj bodo, rotim te, tvoje oči odprte in naj bodo tvoja ušesa pozorna na molitev, ki je narejena na tem kraju.',
        41: 'Sedaj torej vzdigni se, oh Gospod Bog, v svoje počivališče, ti in skrinja tvoje moči. Naj bodo tvoji duhovniki, oh Gospod Bog, oblečeni z rešitvijo duš in naj se tvoji sveti veselijo v dobroti.',
        42: 'Oh Gospod Bog, svojega obraza ne obrni od svojega maziljenca. Spomni se usmiljenj svojega služabnika Davida.‹«',
    },
    7: {
        1: 'Torej ko je Salomon molitvi naredil konec, je z neba prišel ogenj in použil žgalno daritev in klavne daritve in Gospodova slava je napolnila hišo.',
        2: 'Duhovniki niso mogli vstopiti v Gospodovo hišo, ker je Gospodova slava napolnila Gospodovo hišo.',
        3: 'Ko so vsi Izraelovi otroci videli, kako je ogenj prišel dol in Gospodova slava na hišo, so se s svojimi obrazi priklonili do tal na tlak in oboževali ter hvalili Gospoda, rekoč: »Ker je dober, kajti njegovo usmiljenje traja večno.«',
        4: 'Potem so kralj in vse ljudstvo darovali klavne daritve pred Gospodom.',
        5: 'Kralj Salomon je daroval klavno daritev dvaindvajsetih tisočev volov in sto dvanajst tisočev ovc. Tako sta kralj in vse ljudstvo posvetila Božjo hišo.',
        6: 'Duhovniki so čakali na svoje službe. Tudi Lévijevci z Gospodovimi glasbenimi instrumenti. Izdelal jih je kralj David, da hvali Gospoda, kajti njegovo usmiljenje traja večno. Ko je David hvalil ob njihovem služenju in so duhovniki pred njimi trobili s trobentami, je ves Izrael stal.',
        7: 'Poleg tega je Salomon posvetil sredino dvora, ki je bil pred Gospodovo hišo, kajti tam je daroval žgalne daritve in tolščo mirovnih daritev, ker bronast oltar, ki ga je Salomon naredil, ni zmogel sprejeti žgalnih daritev, jedilnih daritev in tolšče.',
        8: 'Prav tako je ob tem času Salomon praznik praznoval sedem dni in ves Izrael z njim, zelo velik shod, od vstopa v Hamát do egiptovske reke.',
        9: 'Na osmi dan so naredili slovesen zbor, kajti sedem dni so praznovali posvetitev oltarja in sedem dni so praznovali.',
        10: 'Na triindvajseti dan sedmega meseca je ljudstvo poslal proč, v njihove šotore, vesele in razigrane v srcu, zaradi dobrote, ki jo je Gospod pokazal Davidu, Salomonu in njegovemu ljudstvu Izraelu.',
        11: 'Tako je Salomon končal Gospodovo hišo in kraljevo hišo in vse, kar je prišlo v Salomonovo srce, da naredi v Gospodovi hiši in v svoji lastni hiši, je uspešno izvršil.',
        12: 'Gospod se je Salomonu prikazal ponoči in mu rekel: »Slišal sem tvojo molitev in ta kraj sem izbral zase, za hišo klavne daritve.',
        13: 'Če zaprem nebo, da ne bo dežja ali če zapovem kobilicam, da požrejo deželo ali če med svoje ljudstvo pošljem kužno bolezen,',
        14: 'če se bo moje ljudstvo, ki je imenovano po mojem imenu, ponižalo, molilo, iskalo moj obraz in se odvrnilo od svojih zlobnih poti, takrat bom prisluhnil iz nebes, odpustil njihov greh in ozdravil njihovo deželo.',
        15: 'Sedaj bodo moje oči odprte in moja ušesa pozorna na molitev, ki je narejena na tem kraju.',
        16: 'Kajti sedaj sem izbral in posvetil to hišo, da bo moje ime lahko tam na veke. Moje oči in moje srce bodo neprestano tam.',
        17: 'Kar se tiče tebe, če hočeš hoditi pred menoj, kakor je hodil tvoj oče David in storiti glede na vse, kar sem ti zapovedal in boš obeleževal moje zakone in moje sodbe,',
        18: 'tedaj bom utrdil prestol tvojega kraljestva, glede na to, kakor sem se zavezal s tvojim očetom Davidom, rekoč: ›Ne bo ti manjkal mož, da bi bil vladar v Izraelu.‹',
        19: 'Toda če se odvrnete in zapustite moje zakone in moje zapovedi, ki sem jih postavil pred vas in boste šli ter služili drugim bogovom in jih oboževali,',
        20: 'potem jih bom s koreninami izpulil iz svoje dežele, ki sem jim jo dal in to hišo, ki sem jo posvetil za svoje ime, bom vrgel iz svojega pogleda in jo naredil, da bo pregovor in tarča posmeha med vsemi narodi.',
        21: 'Ta hiša, ki je visoka, bo osuplost vsakemu, ki gre mimo nje, tako da bo rekel: ›Zakaj je Gospod tako storil tej deželi in tej hiši?‹',
        22: 'To bo odgovor: ›Ker so zapustili Gospoda, Boga svojih očetov, ki jih je privedel ven iz egiptovske dežele in se prijeli drugih bogov, jih oboževali in jim služili. Zato je nanje privedel vse to zlo.‹',
    },
    8: {
        1: 'Pripetilo se je ob koncu dvajsetih let, v katerih je Salomon zgradil Gospodovo hišo in svojo lastno hišo,',
        2: 'da je mesta, ki jih je Hurám povrnil Salomonu, Salomon pozidal in Izraelovim otrokom velel, da prebivajo tam.',
        3: 'Salomon je odšel v Hamát Cobo in prevladal zoper njo.',
        4: 'Zgradil je Tadmór v divjini in vsa skladiščna mesta, ki jih je zgradil v Hamátu.',
        5: 'Zgradil je tudi zgornji Bet Horón in spodnji Bet Horón, utrjeni mesti, z obzidji, velikimi vrati in zapahi,',
        6: 'ter Baalát in vsa skladiščna mesta, ki jih je imel Salomon in vsa mesta bojnih vozov in mesta konjenikov in vse, kar je Salomon želel zgraditi v Jeruzalemu, na Libanonu in po vsej deželi svojega gospostva.',
        7: 'Glede vsega ljudstva, ki je preostalo od Hetejcev, Amoréjcev, Perizéjcev, Hivéjcev in Jebusejcev, ki niso bili iz Izraela,',
        8: 'temveč od njihovih otrok, ki so za njimi ostali v deželi, katerih Izraelovi otroci niso ugonobili, te je Salomon primoral, da plačujejo davek do tega dne.',
        9: 'Toda izmed Izraelovih otrok Salomon ni naredil nobenega služabnika za svoje delo, temveč so bili bojevniki, vodje poveljnikov, poveljniki njegovih bojnih vozov in konjeniki.',
        10: 'Ti so bili vodje častnikov kralja Salomona, celó dvesto petdeset, ki so nadzorovali ljudstvo.',
        11: 'Salomon je iz Davidovega mesta privedel gor faraonovo hčer v hišo, ki jo je zgradil zanjo, kajti rekel je: »Moja žena ne bo prebivala v hiši Izraelovega kralja Davida, ker so prostori, kamor je prišla Gospodova skrinja, sveti.«',
        12: 'Potem je Salomon daroval žgalne daritve Gospodu, na Gospodovem oltarju, ki ga je zgradil pred preddverjem,',
        13: 'celo po določeni meri so vsak dan darovali glede na Mojzesovo zapoved na šabate, na mlaje, na slovesne praznike, trikrat letno, torej na praznik nekvašenega kruha, na praznik tednov in na šotorski praznik.',
        14: 'Glede na red svojega očeta Davida je določil skupine duhovnikov k njihovi službi in Lévijevce k njihovim zadolžitvam, da hvalijo in služijo pred duhovniki, kakor je zahtevala dolžnost vsakega dne. Tudi vratarje po njihovih skupinah pri vsakih velikih vratih, kajti tako je zapovedal David, Božji mož.',
        15: 'Niso se odvrnili od kraljeve zapovedi glede katerekoli zadeve duhovnikov in Lévijevcev ali glede zakladnic.',
        16: 'Torej vse Salomonovo delo je bilo pripravljeno do dneva [položitve] temelja Gospodove hiše in dokler ta ni bila dokončana. Tako je bila Gospodova hiša popolna.',
        17: 'Potem je Salomon odšel v Ecjón Geber in v Elot pri morski obali v edómski deželi.',
        18: 'Hurám mu je po roki svojih služabnikov poslal ladje in služabnike, ki so imeli znanje o morju, in ti so s Salomonovimi služabniki odšli v Ofír in od tam vzeli štiristo petdeset talentov zlata ter jih prinesli kralju Salomonu.',
    },
    9: {
        1: 'Ko je kraljica iz Sabe slišala o Salomonovi slavi, je prišla v Jeruzalem, da Salomona preizkusi s težkimi vprašanji, z zelo veliko skupino in kamelami, ki so nosile dišave, zlata v obilju in dragocene kamne. Ko je prišla k Salomonu, se je z njim posvetovala o vsem, kar je bilo na njenem srcu.',
        2: 'Salomon ji je odgovoril [na] vsa njena vprašanja. Ničesar ni bilo skrito pred Salomonom, česar ji ne bi povedal.',
        3: 'Ko je kraljica iz Sabe videla Salomonovo modrost in hišo, ki jo je zgradil,',
        4: 'hrano njegove mize, sedenje njegovih služabnikov, položaj njegovih služabnikov in njihovo obleko; tudi njegove dvorne točaje in njihovo obleko in njegov vzpon, s katerim je odšel gor v Gospodovo hišo, tam ni bilo več duha v njej.',
        5: 'Kralju je rekla: » To je bilo resnično poročilo, ki sem ga slišala v svoji lastni deželi o tvojih dejanjih in o tvoji modrosti.',
        6: 'Vendar nisem verjela njihovim besedam, dokler nisem prišla in so moje oči to videle. Glej, ni mi bilo povedano niti o eni polovici veličine tvoje modrosti, kajti presegaš slavo, ki sem jo slišala.',
        7: 'Srečni so tvoji možje in srečni so ti tvoji služabniki, ki nenehno stojijo pred teboj in poslušajo tvojo modrost.',
        8: 'Blagoslovljen bodi Gospod, tvoj Bog, ki se je razveseljeval v tebi, da te postavi na svoj prestol, da bi bil kralj za Gospoda, tvojega Boga. Ker je tvoj Bog ljubil Izrael, da jih utrdi na veke, te je zato postavil [za] kralja nad njimi, da izvajaš sodbo in pravico.«',
        9: 'Kralju je izročila sto dvajset talentov zlata, veliko obilje dišav in dragocene kamne. Niti ni bilo tam nobenih takšnih dišav, kot jih je kraljica iz Sabe izročila kralju Salomonu.',
        10: 'Hurámovi služabniki in Salomonovi služabniki, ki so pripeljali zlato iz Ofírja, so pripeljali tudi sandalovino in dragocene kamne.',
        11: 'Kralj je iz sandalovine naredil terase h Gospodovi hiši in h kraljevi palači in harfe ter plunke za pevce. Ničesar takšnega ni bilo prej videti v Judovi deželi.',
        12: 'Kralj Salomon je kraljici iz Sabe izročil vse njene želje, karkoli je prosila, poleg tega, kar je prinesla h kralju. Tako se je obrnila in odšla proč k svoji lastni deželi, ona in njeni služabniki.',
        13: 'Torej teža zlata, ki je prišla k Salomonu v enem letu, je bila šeststo šestinšestdeset talentov zlata,',
        14: 'poleg tega, kar so prinašali krošnjarji in trgovci. Vsi kralji Arabije in voditelji dežele so Salomonu prinašali zlato in srebro.',
        15: 'Kralj Salomon je naredil dvesto okroglih ščitov iz kovanega zlata. Šeststo šeklov iz kovanega zlata je šlo k enemu okroglemu ščitu.',
        16: 'Tristo ščitov je naredil iz kovanega zlata. Tristo šeklov zlata je šlo za en ščit. Kralj jih je postavil v hiši libanonskega gozda.',
        17: 'Poleg tega je kralj naredil velik prestol iz slonovine in ga prevlekel s čistim zlatom.',
        18: 'K prestolu je bilo šest stopnic, s pručko iz zlata, ki so bile pritrjene k prestolu in opori [za roke] na vsaki strani prostora za sedenje in dva leva, stoječa pri oporah [za roke].',
        19: 'Dvanajst levov je stalo tam na eni strani in na drugi, na šestih stopnicah. Ničesar podobnega ni bilo narejenega v nobenem kraljestvu.',
        20: 'Vse posode za pitje kralja Salomona so bile iz zlata in vse posode hiše libanonskega gozda so bile iz čistega zlata. Nobena ni bila iz srebra, le-to ni bilo nič cenjeno v Salomonovih dneh.',
        21: 'Kajti kraljeve ladje so odplule v Taršíš s Hurámovimi služabniki. Enkrat na vsaka tri leta so prišle ladje iz Taršíša, ki so pripeljale zlato, srebro, slonovino, opice in pave.',
        22: 'Kralj Salomon je presegal vse zemeljske kralje v bogastvih in modrosti.',
        23: 'Vsi kralji zemlje so iskali Salomonovo prisotnost, da slišijo njegovo modrost, ki jo je Bog položil v njegovo srce.',
        24: 'Prinašali so mu vsak človek svoje darilo, posode iz srebra, posode iz zlata, oblačila, vprege, dišave, konje in mule, mero leto za letom.',
        25: 'Salomon je imel štiri tisoč boksov za konje in bojne vozove in dvanajst tisoč konjenikov, ki jih je namestil v mestih za bojne vozove in s kraljem v Jeruzalemu.',
        26: 'Kraljeval je nad vsemi kralji od reke celo do dežele Filistejcev in do meje Egipta.',
        27: 'Kralj je naredil srebra v Jeruzalemu kakor kamnov in cedrovih dreves je naredil [toliko] kakor egiptovskih smokev, ki jih je na nizkih ravnicah v obilju.',
        28: 'K Salomonu so vodili konje iz Egipta in iz vseh dežel.',
        29: 'Torej preostala izmed Salomonovih dejanj, prva in zadnja, mar niso zapisana v knjigi preroka Natána in v prerokovanju Šilčana Ahíja in v videnjih vidca Idója zoper Nebátovega sina Jerobeáma?',
        30: 'Salomon je v Jeruzalemu nad Izraelom kraljeval štirideset let.',
        31: 'Salomon je zaspal s svojimi očeti in je bil pokopan v mestu svojega očeta Davida in namesto njega je zakraljeval njegov sin Rehabám.',
    },
    10: {
        1: 'Rehabám je odšel v Sihem, kajti v Sihem je prišel ves Izrael, da ga postavijo za kralja.',
        2: 'Pripetilo se je, ko je Nebátov sin Jerobeám, ki je bil v Egiptu, kamor je pobegnil pred prisotnostjo kralja Salomona, to slišal, da se je Jerobeám vrnil iz Egipta.',
        3: 'Poslali so in ga poklicali. Tako je Jerobeám in ves Izrael prišel in govoril Rehabámu, rekoč:',
        4: '»Tvoj oče je naredil naš jarem boleč. Sedaj torej nekako olajšaj boleče hlapčevstvo svojega očeta in njegov težki jarem, ki ga je nadel na nas in mi ti bomo služili.«',
        5: 'Rekel jim je: »Pridite ponovno k meni po treh dneh.« In ljudstvo je odšlo.',
        6: 'Kralj Rehabám se je posvetoval s starci, ki so stali pred njegovim očetom Salomonom, medtem ko je ta še živel, rekoč: »Kakšen nasvet mi dajete, da temu ljudstvu vrnem odgovor?«',
        7: 'Spregovorili so mu, rekoč: »Če boš prijazen do tega ljudstva, jim ugajal in jim govoril dobre besede, bodo tvoji služabniki na veke.«',
        8: 'Toda zapustil je nasvet, ki so mu ga dali starci in se posvetoval z mladeniči, ki so bili vzgojeni z njim, ki so stali pred njim.',
        9: 'Rekel jim je: »Kakšen nasvet mi daste, da lahko vrnemo odgovor temu ljudstvu, ki mi je govorilo, rekoč: ›Nekoliko olajšaj jarem, ki ga je tvoj oče položil na nas?‹',
        10: 'Mladeniči, ki so bili vzgojeni z njim, so mu spregovorili, rekoč: »Tako boš odgovoril ljudstvu, ki ti je spregovorilo, rekoč: ›Tvoj oče je naš jarem naredil težek, toda ti nam ga nekako olajšaj;‹ tako jim boš rekel: ›Moj mali prst bo debelejši kakor ledja mojega očeta.',
        11: 'Kajti kakor je moj oče na vas položil težek jarem, bom jaz vašemu jarmu še dodal. Moj oče vas je kaznoval z biči, toda jaz vas bom kaznoval s škorpijoni.‹«',
        12: 'Tako so Jerobeám in vse ljudstvo na tretji dan prišli k Rehabámu, kakor je kralj zaukazal, rekoč: »Ponovno pridite k meni na tretji dan.«',
        13: 'Kralj jim je surovo odgovoril in kralj Rehabám je zapustil nasvet starcev',
        14: 'ter jim odgovoril glede na nasvet mladeničev, rekoč: »Moj oče je vaš jarem naredil težek, toda jaz bom k temu dodal. Moj oče vas je kaznoval z biči, toda jaz vas bom kaznoval s škorpijoni.«',
        15: 'Tako kralj ni prisluhnil ljudstvu, kajti razlog je bil od Boga, da je Gospod lahko izpolnil svojo besedo, ki jo je po roki Šilčana Ahíja govoril Nebátovemu sinu Jerobeámu.',
        16: 'Ko je ves Izrael videl, da jim kralj ni hotel prisluhniti, je ljudstvo kralju odgovorilo, rekoč: »Kakšen delež imamo v Davidu? Nobene dediščine nimamo v Jesejevem sinu. Vsak mož k svojim šotorom, oh Izrael. In sedaj, David, glej k svoji lastni hiši.« Tako je ves Izrael odšel k svojim šotorom.',
        17: 'Toda kar se tiče Izraelovih otrok, ki so prebivali v Judovih mestih, je nad njimi kraljeval Rehabám.',
        18: 'Potem je kralj Rehabám poslal Hadoráma, ki je bil nad davkom, Izraelovi otroci pa so ga kamnali s kamni, da je umrl. Toda kralj Rehabám je pohitel, da se spravi gor na svoj bojni voz, da pobegne v Jeruzalem.',
        19: 'In Izrael se upira zoper Davidovo hišo do današnjega dne.',
    },
    11: {
        1: 'Ko je Rehabám prišel v Jeruzalem, je iz Judove in Benjaminove hiše zbral sto osemdeset tisoč izbranih mož, ki so bili bojevniki, da se borijo zoper Izrael, da bi kraljestvo lahko ponovno privedli k Rehabámu.',
        2: 'Toda beseda od Gospoda je prišla Božjemu možu Šemajáju, rekoč:',
        3: '»Govori Rehabámu, Salomonovemu sinu, Judovemu kralju in vsemu Izraelu v Judu in Benjaminu, rekoč:',
        4: '›Tako govori Gospod: ›Ne boste šli gor niti se ne boste borili zoper svoje brate. Vsak mož naj se vrne k svoji hiši, kajti ta stvar je storjena od mene.‹« Ubogali so Gospodove besede in se vrnili pred [tem, da bi] šli zoper Jerobeáma.',
        5: 'Rehabám je prebival v Jeruzalemu in gradil mesta za obrambo v Judu.',
        6: 'Zgradil je celo Bethlehem, Etám, Tekóo,',
        7: 'Bet Cur, Sohóm, Adulám,',
        8: 'Gat, Marešo, Zif,',
        9: 'Adorájim, Lahíš, Azéko,',
        10: 'Coro, Ajalón in Hebrón, ki so v Judu in v Benjaminu utrjena mesta.',
        11: 'Utrdil je oporišča in vanje postavil poveljnike in zaloge živeža, olja in vina.',
        12: 'V vsako posamezno mesto je postavil ščite in sulice ter jih naredil silno močne, [ker je] imel Juda in Benjamin na svoji strani.',
        13: 'Duhovniki in Lévijevci, ki so bili po vsem Izraelu, so zahajali k njemu iz vseh svojih krajev.',
        14: 'Kajti Lévijevci so zapustili svoja predmestja in svojo lastnino ter prišli k Judu in Jeruzalemu, kajti Jerobeám in njegovi sinovi so jih zavrgli pred izvrševanjem duhovniške službe Gospodu.',
        15: 'Odredil si je duhovnike za visoke kraje, za hudiče in za teleti, ki ju je naredil.',
        16: 'Za njimi so iz vseh Izraelovih rodov [prišli] tisti, ki so svoja srca naravnali, da iščejo Gospoda Boga. Iz Izraela so prišli v Jeruzalem, da darujejo Gospodu, Bogu svojih očetov.',
        17: 'Tako so tri leta krepili Judovo kraljestvo in Salomonovega sina Rehabáma naredili močnega, kajti tri leta so hodili po Davidovi in Salomonovi poti.',
        18: '§ Rehabám si je za ženo vzel Mahaláto, hčer Davidovega sina Jerimóta in Abihájilo, hčer Jesejevega sina Eliába,',
        19: 'ki sta mu rodila otroke: Jeúša, Šemarjája in Zaháma.',
        20: 'Za njo je vzel Absalomovo hčer Maáho, ki mu je rodila Abíja, Atája, Zizá in Šelomíta.',
        21: 'Rehabám je ljubil Absalomovo hčer Maáho bolj, kot vse svoje žene in svoje priležnice, (kajti vzel je osemnajst žena in šestdeset priležnic ter zaplodil osemindvajset sinov in šestdeset hčerá.)',
        22: 'Rehabám je postavil Maáhinega sina Abíja, da bo vladar med svojimi brati, kajti mislil je, da ga postavi za kralja.',
        23: 'Modro je ravnal in vse svoje otroke razpršil po vseh Judovih in Benjaminovih deželah, do vsakega utrjenega mesta in dal jim je živeža v obilju. In želel je mnogo žená.',
    },
    12: {
        1: 'Pripetilo se je, ko je Rehabám utrdil kraljestvo in se okrepil, da je zapustil Gospodovo postavo in ves Izrael z njim.',
        2: 'Pripetilo se je, da je v petem letu kralja Rehabáma egiptovski kralj Šišák prišel gor zoper Jeruzalem, ker so se pregrešili zoper Gospoda,',
        3: 's tisoč dvesto bojnimi vozovi in šestdeset tisoč konjeniki. Ljudstva, ki so prišli z njim iz Egipta, je bilo brez števila: Libijci, Súkijci in Etiopci.',
        4: 'Zavzel je utrjena mesta, ki pripadajo Judu in prišel do Jeruzalema.',
        5: 'Potem je prišel prerok Šemajá k Rehabámu in k Judovim princem, ki so bili zaradi Šišáka zbrani skupaj v Jeruzalemu ter jim rekel: ›Tako govori Gospod: ›Vi ste zapustili mene in zato sem tudi jaz vas prepustil v Šišákovo roko.‹«',
        6: 'Nakar so se Izraelovi princi in kralj ponižali ter rekli: » Gospod je pravičen.«',
        7: 'Ko je Gospod videl, da so se ponižali, je beseda od Gospoda prišla k Šemajáju, rekoč: »Oni so se ponižali, zato jih ne bom uničil, temveč jim bom zagotovil nekaj osvoboditve, in moj bes ne bo izlit na Jeruzalem po Šišákovi roki.',
        8: 'Kljub temu bodo njegovi služabniki, da bodo lahko spoznali moje služenje in služenje kraljestvom dežel.«',
        9: 'Tako je egiptovski kralj Šišák prišel gor nad Jeruzalem in odnesel zaklade Gospodove hiše in zaklade kraljeve hiše. Vse je vzel. Odnesel je tudi ščite iz zlata, ki jih je naredil Salomon.',
        10: 'Namesto teh je kralj Rehabám naredil ščite iz brona in jih predal v roke poveljnika straže, ki je varoval vhod kraljeve hiše.',
        11: 'Ko je kralj vstopil v Gospodovo hišo, je prišla straža ter jih nosila in jih [potem] ponovno prinesla v stražarnico.',
        12: 'Ko se je ponižal, se je Gospodov bes odvrnil od njega, da ga ne bi povsem uničil. Tudi v Judu so stvari šle dobro.',
        13: 'Tako se je kralj Rehabám okrepil v Jeruzalemu in kraljeval, kajti Rehabám je bil star enainštirideset let, ko je začel kraljevati in sedemnajst let je kraljeval v Jeruzalemu, mestu, ki ga je Gospod izbral izmed vseh Izraelovih rodov, da tam postavi svoje ime. Ime njegove matere je bilo Naáma, Amónka.',
        14: 'Počel je zlo, ker svojega srca ni pripravil, da išče Gospoda.',
        15: 'Torej dejanja Rehabáma, prva in zadnja, mar niso zapisana v knjigi preroka Šemajája in vidca Idója glede rodovnikov? In nenehno so bile vojne med Rehabámom in Jerobeámom.',
        16: 'Rehabám je zaspal s svojimi očeti in pokopan je bil v Davidovem mestu. Namesto njega je zakraljeval njegov sin Abíja.',
    },
    13: {
        1: 'Torej v osemnajstem letu kralja Jerobeáma, je nad Judom začel kraljevati Abíja.',
        2: 'Tri leta je kraljeval v Jeruzalemu. Ime njegove matere je bilo Mihajá, Uriélova hči iz Gíbee. In bila je vojna med Abíjem in Jerobeámom.',
        3: 'Abíja se je postrojil z vojsko hrabrih bojevnikov, celó štiristo tisoč izbranih mož. Tudi Jerobeám se je postrojil zoper njega z osemsto tisoč izbranimi možmi, ki so bili močni junaški možje.',
        4: 'Abíja je stal na gori Cemarájim, ki je na gori Efrájim in rekel: »Poslušaj me, ti Jerobeám in ves Izrael,',
        5: 'ne veste, da je Gospod, Izraelov Bog, dal kraljestvo nad Izraelom Davidu na veke, celó njemu in njegovim sinovom s solno zavezo?',
        6: 'Vendar je Nebátov sin Jerobeám, služabnik Davidovega sina Salomona, vstal in se uprl zoper svojega gospoda.',
        7: 'In k njemu so bili zbrani praznoglavi možje, Beliálovi otroci in so se okrepili zoper Salomonovega sina Rehabáma, ko je bil Rehabám mlad in nežnega srca in se jim ni mogel zoperstaviti.',
        8: 'In sedaj se vi mislite zoperstaviti Gospodovemu kraljestvu v roki Davidovih sinov. Vas je velika množica in tam sta z vami zlati teleti, katera vam je Jerobeám naredil za bogova.',
        9: 'Mar niste vrgli ven Gospodove duhovnike, Aronove sinove in Lévijevce in ste si naredili duhovnike po načinu narodov drugih dežel? Tako da kdorkoli prihaja, da sebe umésti z mladim bikcem in sedmimi ovni, isti lahko postane duhovnik tistim, ki so ne-bogovi.',
        10: 'Toda kar se nas tiče, je Gospod naš Bog in mi ga nismo zapustili, in duhovniki, ki služijo Gospodu, so Aronovi sinovi in Lévijevci čakajo na svoj posel.',
        11: 'Vsako jutro in vsak večer Gospodu zažigajo žgalne daritve in dišeče kadilo. Tudi hlebe navzočnosti postavljajo na čisto mizo in zlati svečnik z njegovimi svetilkami prižigajo vsak večer. Kajti mi se držimo naročila Gospoda, našega Boga, toda vi ste ga zapustili.',
        12: 'Glejte, sam Bog je z nami za našega poveljnika in njegovi duhovniki z donenjem trobent, da zoper vas zatrobijo alarm. Oh Izraelovi otroci, ne borite se zoper Gospoda, Boga svojih očetov, kajti ne boste uspeli.«',
        13: 'Toda Jerobeám je velel zasedi, da pride naokrog za njimi. Tako so bili pred Judom in zaseda je bila za njimi.',
        14: 'Ko je Juda pogledal nazaj, glej, bitka je bila spredaj in zadaj. Zavpili so h Gospodu in duhovniki so zatrobili s trobentami.',
        15: 'Potem so možje iz Juda zakričali in ko so možje iz Juda zakričali, se je pripetilo, da je Bog udaril Jerobeáma in ves Izrael pred Abíjem in Judom.',
        16: 'Izraelovi otroci so pobegnili pred Judom in Bog jih je izročil v njihovo roko.',
        17: 'Abíja in njegovo ljudstvo jih je umorilo z velikim pokolom. Tako so tam padli umorjeni Izraelci, petsto tisoč izbranih mož.',
        18: 'Tako so bili Izraelovi otroci ob tistem času podjarmljeni, Judovi otroci pa so prevladali, ker so se zanašali na Gospoda, Boga svojih očetov.',
        19: 'Abíja je zasledoval Jerobeáma in od njega vzel mesta: Betel z njegovimi mesti, Ješáno z njenimi mesti in Efrón z njegovimi mesti.',
        20: 'Niti ni Jerobeám ponovno obnovil moči v Abíjevih dneh, in Gospod ga je udaril in je umrl.',
        21: 'Toda Abíja je postal mogočen in poročil štirinajst žena ter zaplodil dvaindvajset sinov in šestnajst hčera.',
        22: 'Ostala Abíjeva dela, njegove poti in njegove besede so zapisane v zgodbi preroka Idója.',
    },
    14: {
        1: 'Tako je Abíja zaspal s svojimi očeti in pokopali so ga v Davidovem mestu. Namesto njega je zakraljeval njegov sin Asá. V njegovih dneh je bila dežela mirna deset let.',
        2: 'Asá je počel to, kar je bilo dobro in pravilno v očeh Gospoda, njegovega Boga,',
        3: 'kajti odstranil je oltarje tujih bogov, visoke kraje, porušil podobe in posekal ašere.',
        4: 'Judu je zapovedal, naj išče Gospoda, Boga njihovih očetov in naj izpolnjuje postavo in zapoved.',
        5: 'Prav tako je iz vseh Judovih mest odstranil visoke kraje in podobe in kraljestvo je bilo pred njim mirno.',
        6: 'V Judu je zgradil utrjena mesta, kajti dežela je imela počitek in v tistih letih ni imel nobene vojne, ker mu je Gospod dal počitek.',
        7: 'Zato je Judu rekel: »Gradimo ta mesta in okrog njih postavimo obzidja, stolpe, velika vrata in zapahe, medtem ko je dežela še pred nami, ker smo iskali Gospoda, svojega Boga. Iskali smo ga in on nam je dal počitek na vsaki strani.« Tako so gradili in bili uspešni.',
        8: 'Asá je imel vojsko mož, ki so nosili okrogle ščite in sulice, iz Juda tristo tisoč in iz Benjamina, ki so nosili ščite in napenjali loke, dvesto osemdeset tisoč. Vsi ti so bili močni junaški možje.',
        9: 'Zoper njih je prišel Etiopijec Zerah z milijonsko vojsko in tristo bojnimi vozmi in prišel do Mareše.',
        10: 'Potem je Asá odšel ven zoper njega in postrojil so se v dolini Cefáti pri Mareši.',
        11: 'Asá je klical h Gospodu, svojemu Bogu in rekel: » Gospod, to zate ni nič, da pomagaš, bodisi z mnogimi ali s tistimi, ki nimajo moči. Pomagaj nam, oh Gospod, naš Bog, kajti nate se zanašamo in v tvojem imenu gremo zoper to množico. Oh Gospod, ti si naš Bog, naj človek ne prevlada zoper tebe.«',
        12: 'Tako je Gospod udaril Etiopijce pred Asájem in pred Judom in Etiopijci so pobegnili.',
        13: 'Asá in ljudstvo, ki je bilo z njim, so jih preganjali do Gerárja in Etiopijci so bili premagani, da si niso več opomogli, kajti bili so uničeni pred Gospodom in njegovo vojsko in odnesli so zelo veliko plena.',
        14: 'Udarili so vsa mesta naokoli Gerárja, kajti Gospodov strah je prišel nanje. Oplenili so vsa mesta, kajti v njih je bilo silno veliko plena.',
        15: 'Udarili so tudi šotore živine in odvedli proč ovc in kamel v obilju ter se vrnili v Jeruzalem.',
    },
    15: {
        1: 'Božji Duh je prišel nad Odédovega sina Azarjá.',
        2: 'Ta je odšel ven, da sreča Asája in mu rekel: »Prisluhni mi, Asá, ves Juda in Benjamin. Gospod je z vami, dokler ste vi z njim in če ga iščete, se vam bo dal najti, toda če ga zapustite, bo on zapustil vas.',
        3: 'Torej dolgo časa je bil Izrael brez resničnega Boga, brez duhovnika, ki bi učil in brez postave.',
        4: 'Toda ko so se v svoji stiski obrnili h Gospodu, Izraelovemu Bogu in ga iskali, se jim je dal najti.',
        5: 'V tistih časih ni bilo miru tistemu, ki je odšel ven niti tistemu, ki je vstopil, temveč so bile velike nevšečnosti nad vsemi prebivalci dežel.',
        6: 'Narod je bil uničen od naroda in mesto od mesta, kajti Bog jih je jezil z vsemi nadlogami.',
        7: 'Bodite torej močni in vaše roke naj ne bodo šibke, kajti vaše delo bo nagrajeno.«',
        8: 'Ko je Asá slišal te besede in prerokbo preroka Odéda, se je opogumil in odstranil gnusne malike iz vse Judove in Benjaminove dežele in iz mest, ki jih je vzel z gore Efrájim in obnovil Gospodov oltar, ki je bil pred Gospodovim preddverjem.',
        9: 'Zbral je ves Juda in Benjamin in z njimi tujce iz Efrájima, Manáseja in Simeona, kajti iz Izraela so se v obilju zatekali k njemu, ko so videli, da je bil Gospod, njegov Bog, z njim.',
        10: 'Tako so se zbrali skupaj pri Jeruzalemu, v tretjem mesecu, v petnajstem letu Asájevega kraljevanja.',
        11: 'Isti čas so darovali Gospodu od plena, ki so ga privedli, sedemsto volov in sedemsto ovc.',
        12: 'Vstopili so v zavezo, da iščejo Gospoda, Boga svojih očetov, z vsem svojim srcem in z vso svojo dušo,',
        13: 'da kdorkoli ne bi iskal Gospoda, Izraelovega Boga, bi bil usmrčen, bodisi majhen ali velik, moški ali ženska.',
        14: 'In prisegli so Gospodu z močnim glasom, vriskanjem, s trobentami in kornéti.',
        15: 'Ves Juda se je veselil ob prisegi, kajti prisegli so z vsem svojim srcem in ga iskali z vso svojo željo in on se jim je dal najti. In Gospod jim je dal počitek naokoli.',
        16: 'Tudi glede Maáhe, matere kralja Asája, jo je ta odstranil, da bi bila kraljica, ker si je naredila malika v ašeri. Asá je posekal njenega malika, ga poteptal in ga zažgal pri potoku Kidron.',
        17: 'Toda visoki kraji niso bili odvzeti iz Izraela. Kljub temu je bilo Asájevo srce vse njegove dni popolno.',
        18: 'V Božjo hišo je prinesel stvari, ki jih je njegov oče posvetil in te, ki jih je sam posvetil: srebro, zlato in posode.',
        19: 'In nobene vojne ni bilo več do petintridesetega leta Asájevega kraljevanja.',
    },
    16: {
        1: 'V šestintridesetem letu Asájevega kraljevanja je zoper Juda prišel Izraelov kralj Bašá in gradil Ramo z namenom, da nikomer ne bi dovolil iti ven ali priti noter k Judovemu kralju Asáju.',
        2: 'Potem je Asá prinesel ven srebro in zlato iz zakladnic Gospodove hiše in kraljeve hiše ter poslal k sirskemu kralju Ben Hadádu, ki je prebival v Damasku, rekoč:',
        3: '»Zaveza je med menoj in teboj, kakor je bila med mojim očetom in tvojim očetom. Glej, poslal sem ti srebro in zlato; pojdi in prelomi svojo zavezo z Izraelovim kraljem Bašájem, da lahko odide od mene.«',
        4: 'Ben Hadád je prisluhnil kralju Asáju in poslal poveljnike svoje vojske zoper Izraelova mesta in udarili so Ijón, Dan, Abél Majim in vsa Neftálijeva skladiščna mesta.',
        5: 'Pripetilo se je, ko je Bašá to slišal, da je prenehal graditi Ramo in opustil svoje delo.',
        6: 'Potem je kralj Asá vzel vsega Juda in odnesli so proč kamenje iz Rame in njen les, s katerim je Bašá gradil; s tem je gradil Gebo in Micpo.',
        7: 'Ob tistem času je k Judovemu kralju Asáju prišel videc Hananí in mu rekel: »Ker si se zanašal na sirskega kralja in se nisi zanesel na Gospoda, svojega Boga, zato je vojska sirskega kralja pobegnila iz tvoje roke.',
        8: 'Mar niso bili Etiopijci in Libijci ogromna vojska z mnogimi bojnimi vozovi in konjeniki? Vendar ker si se zanesel na Gospoda, jih je izročil v tvojo roko.',
        9: 'Kajti Gospodove oči tekajo sem ter tja po vsej celotni zemlji, da se izkaže močnega v korist tistih, katerih srce je popolno do njega. V tem si storil nespametno, zato boš od sedaj naprej imel vojne.',
        10: 'Potem je bil Asá ogorčen nad vidcem in ga vrgel v jetnišnico, kajti zaradi te stvari je bil ogorčen nanj. In Asá je isti čas zatiral nekatere izmed ljudstva.',
        11: 'Glej, dejanja Asája, prva in zadnja, glej, ta so zapisana v knjigi Judovih in Izraelovih kraljev.',
        12: 'Asá je bil v devetintridesetem letu svojega kraljevanja bolan na svojih stopalih, dokler ni bila njegova bolezen silno velika, vendar se v svoji bolezni ni obrnil h Gospodu, temveč k zdravnikom.',
        13: 'Asá je zaspal s svojimi očeti in umrl v enainštiridesetem letu svojega kraljevanja.',
        14: 'Pokopali so ga v njegovih lastnih mavzolejih, ki si jih je naredil zase v Davidovem mestu in ga položili v posteljo, ki je bila napolnjena s prijetnimi dišavami in različnimi vrstami dišav, pripravljenih po lekarnarski umetnosti. Zanj so naredili zelo velik sežig [dišav].',
    },
    17: {
        1: 'Namesto njega je zakraljeval njegov sin Józafat in se okrepil zoper Izraela.',
        2: 'Namestil je sile v vsa utrjena Judova mesta in postavil garnizije v Judovi deželi in v Efrájimovih mestih, ki jih je zavzel njegov oče Asá.',
        3: 'Gospod je bil z Józafatom, ker je hodil po prvih poteh svojega očeta Davida in ni iskal Báalov,',
        4: 'temveč je sledil Gospodu, Bogu svojega očeta in hodil po njegovih zapovedih in ne po Izraelovih ravnanjih.',
        5: 'Zato je Gospod utrdil kraljestvo v njegovi roki. Ves Juda je Józafatu prinesel darila in imel je bogastva, čast in obilje.',
        6: 'Njegovo srce je bilo vzdignjeno na Gospodovih poteh. Poleg tega je iz Juda odstranil visoke kraje in ašere.',
        7: 'Tudi v tretjem letu svojega kraljevanja je poslal k svojim princem, torej k Ben Hajilu, k Obadjáju, k Zeharjáju, k Netanélu in k Mihajáju, da bi učili po Judovih mestih.',
        8: 'Z njimi je poslal Lévijevce, torej Šemajája, Netanjája, Zebadjája, Asaéla, Šemiramóta, Jehonatana, Adoníja, Tobija, Tob Adoníja, Lévijevce in z njimi duhovnika Elišamája in Jehoráma.',
        9: 'Učili so v Judu in s seboj so imeli knjigo Gospodove postave in šli so naokoli po vseh Judovih mestih in učili ljudstvo.',
        10: 'Gospodov strah je padel na vsa kraljestva dežel, ki so bile naokoli Juda, tako da zoper Józafata niso bojevali nobene vojne.',
        11: 'Tudi nekateri izmed Filistejcev so Józafatu prinesli darila in davek srebra. Arabci so mu privedli trope, sedem tisoč sedemsto ovnov in sedem tisoč sedemsto kozlov.',
        12: 'Józafat je postal silno velik in v Judu je zgradil gradove in skladiščna mesta.',
        13: 'Po Judovih mestih je imel mnogo posla. In v Jeruzalemu so bili bojevniki, močni junaški možje.',
        14: 'To so njihova števila glede na hišo njihovih očetov. Iz Juda poveljniki nad tisočimi: vodja Adnáh in z njim tristo tisoč močnih junaških mož.',
        15: 'Poleg njega je bil poveljnik Johanán in z njim dvesto osemdeset tisoč.',
        16: 'Poleg njega je bil Zihríjev sin Amasjá, ki se je voljno daroval Gospodu in z njim dvesto tisoč močnih junaških mož.',
        17: 'Od Benjamina Eljadá, mogočen hraber mož in z njim dvesto tisoč z lokom in ščitom oboroženih mož.',
        18: 'Poleg njega je bil Jozabád in z njim sto osemdeset tisoč pripravljenih za vojno.',
        19: 'Ti so čakali na kralja, poleg tistih, ki jih je kralj namestil v utrjenih mestih po vsem Judu.',
    },
    18: {
        1: 'Torej Józafat je imel bogastev in časti v obilju in sklenil svaštvo z Ahábom.',
        2: 'Po nekaj letih je odšel dol k Ahábu v Samarijo. Aháb je zanj in za ljudstvo, ki ga je imel s seboj, v obilju zaklal ovce in vole in pregovoril ga je, da gre z njim gor v Ramót Gileád.',
        3: 'Izraelov kralj Aháb je rekel Judovemu kralju Józafatu: »Hočeš iti z menoj v Ramót Gileád?« Ta mu je odgovoril: »Jaz sem, kakor si ti in moje ljudstvo kakor tvoje ljudstvo, in mi bomo s teboj v vojni.«',
        4: 'Józafat je Izraelovemu kralju rekel: »Poizvedi, prosim te, danes pri Gospodovi besedi.«',
        5: 'Zato je Izraelov kralj izmed prerokov skupaj zbral štiristo mož in jim rekel: »Ali naj gremo v Ramót Gileád, da se bojujemo ali naj [to] opustim?« Rekli so: »Pojdi gor, kajti Bog ga bo izročil v kraljevo roko.«',
        6: 'Toda Józafat je rekel: » Ali tukaj poleg ni Gospodovega preroka, da bi lahko poizvedeli od njega?',
        7: 'Izraelov kralj je Józafatu rekel: » Je še en mož, pri katerem bi lahko povprašali Gospoda, toda jaz ga sovražim, kajti nikoli mi ne prerokuje dobro, temveč vedno hudo. Ta isti je Jimlájev sin Miha.« Józafat je rekel: »Naj kralj ne govori tako.«',
        8: 'Izraelov kralj je dal poklicati enega izmed svojih častnikov in rekel: »Pojdi hitro po Jimlájevega sina Miha.«',
        9: 'Izraelov kralj in Judov kralj Józafat sta sedela, vsak izmed njiju na svojem prestolu, oblečena v njuna svečana oblačila in sedela na odprtem kraju pri vhodu velikih vrat Samarije, vsi preroki pa so prerokovali pred njima.',
        10: 'Kenaanájev sin Cidkijá si je naredil rogove iz železa in rekel: »Tako govori Gospod: ›S temi boš porinil Sirijo, dokler ne bodo použiti.',
        11: 'Vsi preroki so prerokovali tako, rekoč: »Pojdi gor v Ramót Gileád in uspevaj, kajti Gospod ga bo izročil v kraljevo roko.«',
        12: 'Poslanec, ki je odšel, da pokliče Miha, mu je spregovoril, rekoč: »Glej, besede prerokov soglasno kralju razglašajo dobro. Naj bo torej tvoja beseda, prosim te, kakor ena izmed njihovih in govori dobro.«',
        13: 'Miha je rekel: » Kakor živi Gospod, kar reče moj Bog, to bom govoril.«',
        14: 'Ko je prišel h kralju, mu je kralj rekel: »Miha, ali naj gremo gor v Ramót Gileád, da se bojujemo ali naj [to] opustim?« Ta je rekel: »Pojdite gor in uspevajte in izročeni bodo v vašo roko.«',
        15: 'Kralj mu je rekel: »Kolikokrat te bom zaklinjal, da mi ne poveš ničesar, razen resnice, v Gospodovem imenu?«',
        16: 'Potem je rekel: »Videl sem vsega Izraela razkropljenega po gorah kakor ovce, ki nimajo pastirja in Gospod je rekel: ›Ti nimajo gospodarja, naj se torej vrnejo v miru, vsak mož k svoji hiši.‹«',
        17: 'Izraelov kralj je Józafatu rekel: »Ali ti nisem rekel, da mi ne bo prerokoval dobro, temveč zlo?«',
        18: 'Ponovno je rekel: »Zato poslušajte besedo od Gospoda: ›Videl sem Gospoda sedeti na svojem prestolu in vso nebeško vojsko stati na njegovi desni roki in na njegovi levi.‹',
        19: 'Gospod je rekel: ›Kdo bo premamil Izraelovega kralj Ahába, da gre lahko gor in pade pri Ramót Gileádu?‹ Eden je odgovoril na ta način, drugi je odgovoril na ta način.',
        20: 'Tedaj je šel naprej duh in obstal pred Gospodom ter rekel: ›Jaz ga bom premamil.‹ Gospod mu je rekel: ›S čim?‹',
        21: 'Rekel je: ›Šel bom ven in bom lažniv duh v ustih vseh njegovih prerokov.‹ In Gospod je rekel: ›Ti ga boš premamil in ti ga boš tudi pregovoril. Pojdi ven in stôri tako.‹',
        22: 'Zdaj torej glejte, Gospod je položil lažnivega duha v usta teh tvojih prerokov in Gospod je zoper tebe govoril zlo.«',
        23: 'Potem je Kenaanájev sin Cidkijá prišel bliže in udaril Miha po licu ter rekel: »Katero pot je odšel Gospodov duh od mene, da govori tebi?«',
        24: 'Miha je rekel: »Glej, videl boš ta dan, ko boš šel v notranjo sobo, da se skriješ.«',
        25: 'Potem je Izraelov kralj rekel: »Vzemite Miha in ga odvedite nazaj k Amónu, voditelju mesta in h kraljevemu sinu Joášu',
        26: 'ter recite: ›Tako govori kralj: ›Tega pajdaša postavita v ječo in ga hranita s kruhom stiske in z vodo stiske, dokler se ne vrnem v miru.‹«',
        27: 'Miha je rekel: »Če se zagotovo vrneš v miru, potem po meni ni govoril Gospod.« Rekel je [še]: »Prisluhnite vsa ve ljudstva.«',
        28: 'Tako sta Izraelov kralj in Judov kralj Józafat odšla gor do Ramót Gileáda.',
        29: 'Izraelov kralj je Józafatu rekel: »Preoblekel se bom in šel v bitko, toda ti si nadeni svoja svečana oblačila.« Tako se je Izraelov kralj preoblekel in odšla sta na bitko.',
        30: 'Torej sirski kralj je zapovedal poveljnikom bojnih vozov, ki so bili z njim, rekoč: »Ne borite se z malim ali velikim, razen samo z Izraelovim kraljem.«',
        31: 'Pripetilo se je, ko so poveljniki bojnih vozov zagledali Józafata, da so rekli: »Ta je Izraelov kralj.« Zato so ga obdali, da se bojujejo, toda Józafat je zavpil in Gospod mu je pomagal in Bog jih je spodbodel, da odidejo od njega.',
        32: 'Kajti pripetilo se je, da ko so poveljniki bojnih vozov zaznali, da to ni bil Izraelov kralj, so se ponovno obrnili nazaj od zasledovanja [za] njim.',
        33: 'Nek mož pa je preprosto napel lok in Izraelovega kralja zadel med člene prsnega oklepa. Zato je vozniku svojega bojnega voza rekel: »Obrni svojo roko, da me lahko odvedeš iz vojske, kajti ranjen sem.«',
        34: 'Bitka je ta dan narasla, vendar je Izraelov kralj sam stal pokonci na svojem bojnem vozu zoper Sirce do večera, okoli časa zahajanja sonca pa je umrl.',
    },
    19: {
        1: 'Judov kralj Józafat pa se je v miru vrnil k svoji hiši v Jeruzalem.',
        2: 'Hananíjev sin Jehú, videc, je odšel ven, da ga sreča in kralju Józafatu rekel: »Ali naj bi pomagal brezbožnikom in ljubil tiste, ki sovražijo Gospoda? Zato je izpred Gospoda na tebi bes.',
        3: 'Kljub temu so v tebi najdene dobre stvari v tem, da si iz dežele odvzel ašere in si svoje srce pripravil, da išče Boga.',
        4: 'Józafat je prebival v Jeruzalemu. In odšel je ponovno ven skozi ljudstvo od Beeršébe do gore Efrájim in jih vodil nazaj h Gospodu, Bogu njihovih očetov.',
        5: 'Postavil je sodnike vsepovsod po deželi, po vseh utrjenih Judovih mestih, mestu za mestom',
        6: 'in sodnikom rekel: »Pazite, kaj počnete, kajti ne sodite za človeka, temveč za Gospoda, ki je z vami v sodbi.',
        7: 'Zatorej naj bo sedaj nad vami Gospodov strah. Pazite in to storite, kajti z Gospodom, svojim Bogom, ni krivičnosti, niti oziranja na osebe, niti sprejemanja darov.',
        8: 'Poleg tega je v Jeruzalemu Józafat postavil od Lévijevcev in od duhovnikov in od vodij Izraelovih očetov za Gospodovo sodbo in za oporekanja, ko so se vrnili v Jeruzalem.',
        9: 'Zadolžil jih je, rekoč: »To boste delali v Gospodovem strahu, zvesto in s popolnim srcem.',
        10: 'Kakršnakoli zadeva bo prišla k vam od vaših bratov, ki prebivajo v svojih mestih, med krvjo in krvjo, med postavo in zapovedjo, zakoni in sodbami, jih boste torej opozorili, da ne prestopajo zoper Gospoda in tako [ne] pride bes nad vas in nad vaše brate. To delajte in se ne boste pregrešili.',
        11: 'Glejte, véliki duhovnik Amarjá je nad vami v vseh Gospodovih zadevah in Jišmaélov sin Zebadjá, vladar Judove hiše, za vse kraljeve zadeve. Prav tako bodo Lévijevci častniki pred vami. Postopajte pogumno in Gospod bo z dobrim.«',
    },
    20: {
        1: 'Po tem se je tudi pripetilo, da so Moábovi otroci, Amónovi otroci in z njimi drugi, poleg Amóncev, prišli zoper Józafata, da se vojskujejo.',
        2: 'Potem so prišli nekateri, ki so Józafatu rekli: »Velika množica prihaja zoper tebe, iz druge strani morja, na to stran Sirije. Glej, oni so v Hacecón Tamáru, ki je En Gedi.',
        3: 'Józafat se je zbal in se pripravil, da išče Gospoda in je po vsem Judu razglasil post.',
        4: 'Juda se je zbral skupaj, da prosi pomoč od Gospoda. Celo iz vseh Judovih mest so prišli, da iščejo Gospoda.',
        5: 'Józafat je stal v skupnosti Judovcev in Jeruzalemcev, v Gospodovi hiši, pred novim dvorom',
        6: 'in rekel: »Oh Gospod, Bog naših očetov, ali nisi ti Bog v nebesih? In ali ne vladaš nad vsemi kraljestvi poganov? In ali ni v tvoji roki oblast in moč, tako da se ti nihče ne more zoperstaviti?',
        7: 'Mar nisi ti naš Bog, ki si napodil prebivalce te dežele pred svojim ljudstvom Izraelom in jo daješ potomcem svojega prijatelja Abrahama na veke?',
        8: 'In oni prebivajo v njej in so ti v njej zgradili svetišče za tvoje ime, rekoč:',
        9: '›Če zlo prihaja nad nas kakor meč, sodba ali kužna bolezen ali lakota, mi stojimo pred to hišo in v tvoji prisotnosti (kajti tvoje ime je v tej hiši) in kličemo k tebi v svoji stiski, potem boš slišal in pomagal.',
        10: 'In sedaj glej, Amónovi in Moábovi otroci in gorovje Seír, za katere nisi hotel, da jih Izraelci napadejo, ko so prišli iz egiptovske dežele, temveč so se obrnili od njih in jih niso uničili,',
        11: 'glej pravim, kako so nas nagradili, da pridejo, da nas vržejo ven iz tvoje posesti, ki si nam jo ti dal, da jo podedujemo.',
        12: 'Oh naš Bog, mar jih ne boš sodil? Kajti nobene moči nimamo zoper to veliko skupino, ki prihaja zoper nas niti ne vemo, kaj storiti, temveč so naše oči na tebi.«',
        13: 'Ves Juda je stal pred Gospodom s svojimi malčki, svojimi ženami in svojimi otroki.',
        14: 'Potem je nad Jahaziéla, sina Zeharjája, sina Benajája, sina Jeiéla, sina Matanjája, Lévijevca izmed Asáfovih sinov, prišel Duh od Gospoda v sredo skupnosti',
        15: 'in rekel je: »Prisluhnite, ves Juda in prebivalci Jeruzalema in ti, kralj Józafat: ›Tako vam govori Gospod: ›Ne bojte se niti ne bodite zaprepadeni zaradi te velike množice, kajti bitka ni vaša, temveč Božja.',
        16: 'Jutri pojdite dol zoper njih. Glejte, prišli bodo pri pečini Cic in našli jih boste na koncu potoka, pred jeruélsko divjino.',
        17: 'V tej bitki se vam ne bo treba bojevati. Razpostavite se, stojte mirno in glejte rešitev duš Gospoda z vami, oh Juda in Jeruzalem. Ne bojte se niti ne bodite zaprepadeni. Jutri pojdite ven zoper njih, kajti Gospod bo z vami.‹«',
        18: 'Józafat je sklonil svojo glavo s svojim obrazom do tal in ves Juda in prebivalci Jeruzalema so padli pred Gospodom in oboževali Gospoda.',
        19: 'Lévijevci izmed otrok Kehátovcev in izmed Kórahovcev so vstali, da hvalijo Gospoda, Izraelovega Boga, s silno močnim glasom.',
        20: 'Zgodaj zjutraj so vstali ter odšli naprej v divjino Tekóe in ko so šli naprej se je Józafat ustavil in rekel: »Poslušajte me, oh Juda in vi, prebivalci Jeruzalema. Verjemite v Gospoda, svojega Boga, tako boste utrjeni; verjemite prerokom, tako boste uspeli.«',
        21: 'Ko se je posvetoval z ljudstvom, je določil pevce za Gospoda in ki naj bi hvalili lepoto svetosti, medtem ko bodo šli ven pred vojsko in govorili: »Hvalite Gospoda, kajti njegovo usmiljenje vztraja na veke.«',
        22: 'Ko so začeli peti in hvaliti, je Gospod pripravil zasede zoper otroke Amóna, Moába in gorovje Seír, ki so prišli zoper Juda; in bili so udarjeni.',
        23: 'Kajti otroci Amóna in Moába so se dvignili zoper prebivalce gorovja Seír, da jih popolnoma pobijejo in uničijo. In ko so prebivalcem Seíra storili konec, je vsakdo pomagal uničiti drugega.',
        24: 'Ko je Juda prišel proti stražnemu stolpu v divjini, so pogledali k množici in glej, bili so trupla, padla na zemljo in nihče ni pobegnil.',
        25: 'Ko je Józafat in njegovo ljudstvo prišlo, da od njih poberejo plen, so med njimi našli v obilju tako bogastev s trupli, kakor dragocene dragulje, ki so jih pobrali zase, več kakor so lahko nesli in tam so bili tri dni pri pobiranju plena, toliko ga je bilo.',
        26: 'Na četrti dan so se zbrali skupaj v dolini Berahá, kajti tam so blagoslovili Gospoda. Zato je bilo ime tega kraja imenovano dolina Berahá do današnjega dne.',
        27: 'Potem so se vrnili, vsak človek iz Juda in Jeruzalema in Józafat na njihovem čelu, da gredo ponovno z radostjo v Jeruzalem, kajti Gospod jim je storil, da se veselijo nad svojimi sovražniki.',
        28: 'V Jeruzalem so prišli s plunkami, harfami in trobentami h Gospodovi hiši.',
        29: 'Božji strah je bil na vseh kraljestvih tistih dežel, ko so slišali, da se je Gospod boril zoper Izraelove sovražnike.',
        30: 'Tako je bilo Józafatovo kraljestvo mirno, kajti njegov Bog mu je naokoli dal počitek.',
        31: 'Józafat je kraljeval nad Judom. Petintrideset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval petindvajset let. Ime njegove matere je bilo Azúba, Šilhíjeva hči.',
        32: 'Hodil je po poti svojega očeta Asája in se ni oddvojil od nje in delal je to, kar je bilo pravilno v Gospodovih očeh.',
        33: 'Vendar visoki kraji niso bili odstranjeni, kajti do takrat ljudstvo svojih src še ni pripravilo k Bogu njihovih očetov.',
        34: 'Torej preostala izmed Józafatovih dejanj, prva in zadnja, glej, ta so zapisana v knjigi Hananijevega sina Jehúja, ki je omenjen v knjigi Izraelovih kraljev.',
        35: 'Potem je Judov kralj Józafat sebe pridružil Izraelovemu kralju Ahazjáju, ki je počel zelo zlobno.',
        36: 'Pridružil se mu je, da izdelata ladje, da bi plule v Taršíš in ladje so izdelali v Ecjón Geberju.',
        37: 'Potem je Dodavájev sin Eliézer iz Maréše prerokoval zoper Józafata, rekoč: »Ker si se pridružil Ahazjáju, je Gospod zlomil tvoja dela.« In ladje so bile razbite, da niso mogle pluti v Taršíš.',
    },
    21: {
        1: 'Torej Józafat je zaspal s svojimi očeti in bil s svojimi očeti pokopan v Davidovem mestu. Namesto njega je zakraljeval njegov sin Jehorám.',
        2: 'Ta je imel brate, Józafatove sinove: Azarjája, Jehiéla, Zeharjája, Azarjája, Mihaela in Šefatjája. Vsi ti so bili sinovi Izraelovega kralja Józafata.',
        3: 'Njihov oče jim je dal veliko daril iz srebra in iz zlata in dragocenih stvari, z utrjenimi mesti v Judu, toda kraljestvo je dal Jehorámu, ker je bil prvorojenec.',
        4: 'Torej ko je bil Jehorám dvignjen h kraljestvu svojega očeta, se je okrepil in vse svoje brate usmrtil z mečem in tudi številne izmed Izraelovih princev.',
        5: 'Jehorám je bil star dvaintrideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval osem let.',
        6: 'Hodil je po poti Izraelovih kraljev, podobno kakor je storila Ahábova hiša, kajti za ženo je imel Ahábovo hčer. Počel je to, kar je bilo zlo v Gospodovih očeh.',
        7: 'Vendar Gospod ni hotel uničiti Davidove hiše zaradi zaveze, ki jo je sklenil z Davidom in kakor je obljubil, da da luč njemu in njegovim sinovom na veke.',
        8: 'V njegovih dneh so se Edómci spuntali izpod Judovega gospostva in si postavili kralja.',
        9: 'Potem je Jehorám s svojimi princi odšel naprej in vsi njegovi bojni vozovi z njim. Ponoči je vstal in udaril Edomce, ki so obkolili njega in stotnike bojnih vozov.',
        10: 'Tako so se Edómci spuntali izpod Judove roke do današnjega dne. Isti čas se je tudi Libna spuntala izpod njegove roke, ker je zapustil Gospoda, Boga svojih očetov.',
        11: 'Poleg tega je postavil visoke kraje po Judovih gorah in prebivalcem Jeruzalema storil, da zagrešijo prešuštvovanje in k temu zapeljal Juda.',
        12: 'In k njemu je prišlo pisanje preroka Elija, rekoč: ›Tako govori Gospod, Bog tvojega očeta Davida: ›Ker nisi hodil po poteh svojega očeta Józafata niti po poteh Judovega kralja Asája,',
        13: 'temveč si hodil po poti Izraelovih kraljev in si pripravil Juda in prebivalce Jeruzalema, da se vlačugajo, podobno vlačugarstvom Ahábove hiše in si tudi umoril svoje brate od hiše svojega očeta, ki so bili boljši kakor ti sam.',
        14: 'Glej, z veliko nadlogo bo Gospod udaril tvoje ljudstvo, tvoje otroke, tvoje žene in vse tvoje dobrine,',
        15: 'ti pa boš imel veliko slabost z boleznijo svoje notranjosti, dokler tvoja notranjost ne zleze ven zaradi razloga bolezni dan za dnem.«',
        16: 'Poleg tega je Gospod zoper Jehoráma razvnel duha Filistejcev in Arabcev, ki so bili blizu Etiopijcev.',
        17: 'Ti so prišli gor v Juda in vdrli vanj in odnesli vse imetje, ki je bilo najdeno v kraljevi hiši in tudi njegove sinove in njegove žene, tako da mu ni ostal sin razen Joaháza, najmlajšega izmed njegovih sinov.',
        18: 'Po vsem tem ga je Gospod udaril v njegovi notranjosti z neozdravljivo boleznijo.',
        19: 'Pripetilo se je tekom časa, po koncu dveh let, da je njegova notranjost zlezla ven zaradi razloga njegove slabosti. Tako je umrl od hudih bolezni. Njegovo ljudstvo zanj ni naredilo nobenega sežiga [dišav], podobnega sežigu njegovim očetom.',
        20: 'Dvaintrideset let je bil star, ko je začel kraljevati in v Jeruzalemu je kraljeval osem let in odšel, brez da bi ga želeli. Vendar so ga pokopali v Davidovem mestu, toda ne v kraljevih mavzolejih.',
    },
    22: {
        1: 'Prebivalci Jeruzalema so namesto njega za kralja postavili njegovega najmlajšega sina Ahazjája, kajti četa mož, ki je prišla z Arabci k taboru, je umorila vse starejše. Tako je zakraljeval Ahazjá, sin Judovega kralja Jehoráma.',
        2: 'Ahazjá je bil star dvainštirideset let, ko je začel kraljevati in v Jeruzalemu je kraljeval eno leto. Ime njegove matere je bilo Ataljá, Omrijeva hči.',
        3: 'Tudi on je hodil po poteh Ahábove hiše, kajti njegova mati je bila njegova svetovalka, da počne zlobno.',
        4: 'Zaradi česar je počel zlo v Gospodovih očeh, kakor Ahábova hiša, kajti bili so njegovi svetovalci po smrti njegovega očeta, njemu v uničenje.',
        5: 'Hodil je tudi po njihovem nasvetu in odšel z Ahábovim sinom Jehorámom, Izraelovim kraljem, da se vojskuje zoper sirskega kralja Hazaéla pri Ramót Gileádu. Sirci pa so udarili Joráma.',
        6: 'Vrnil se je, da bi bil ozdravljen v Jezreélu, zaradi ran, ki so mu bile zadane pri Rami, ko se je boril s sirskim kraljem Hazaélom. In Azarjá, Jehorámov sin, Judov kralj, je odšel dol, da pogleda Ahábovega sina Jehoráma pri Jezreélu, ker je bil bolan.',
        7: 'To je bilo od Boga, da je prišlo k Ahazjáju uničenje, da je šel k Jehorámu, kajti ko je prišel, je z Jehorámom odšel ven zoper Nimšíjevega sina Jehúja, ki ga je Gospod mazilil, da iztrebi Ahábovo hišo.',
        8: 'Pripetilo se je, da ko je Jehú izvrševal sodbo nad Ahábovo hišo in našel Judove prince in sinove Ahazjájevih bratov, da služijo Ahazjáju, jih je usmrtil.',
        9: 'Iskal je Ahazjá, in ujeli so ga (kajti skrit je bil v Samariji) ter ga privedli k Jehúju. Ko so ga umorili, so ga pokopali: »Ker,« so rekli, »on je Józafatov sin, ki je z vsem svojim srcem iskal Gospoda.« Tako Ahazjájeva hiša ni imela moči, da kraljestvo obdrži mirno.',
        10: 'Toda ko je Ahazjájeva mati Ataljá videla, da je bil njen sin mrtev, je vstala in uničila vse kraljeve potomce Judove hiše.',
        11: 'Toda kraljeva hči Jošébah je vzela Ahazjájevega sina Joáša in ga ukradla izmed kraljevih sinov, ki so bili umorjeni in postavila njega ter njegovo dojiljo v spalnico. Tako ga je Jošébah, hči kralja Jehoráma, žena duhovnika Jojadája (kajti bila je Ahazjájeva sestra) skrila pred Ataljo, tako da ga ta ni usmrtila.',
        12: 'Šest let je bil z njimi skrit v Božji hiši, Ataljá pa je kraljevala nad deželo.',
    },
    23: {
        1: 'V sedmem letu se je Jojadá okrepil in vzel poveljnike nad stotimi: Jerohámovega sina Azarjája, Johanánovega sina Jišmaéla, Obédovega sina Azarjája, Adajájevega sina Maasejája in Zihríjevega sina Elišafáta v zavezo z njim.',
        2: 'Ti so šli naokoli po Judu in zbrali Lévijevce iz vseh Judovih mest in vodje Izraelovih očetov ter prišli v Jeruzalem.',
        3: 'Vsa skupnost je sklenila zavezo s kraljem v Božji hiši. Rekel jim je: »Glejte, kraljev sin bo kraljeval, kakor je Gospod rekel o Davidovih sinovih.',
        4: 'To je stvar, ki jo boste storili: ›Tretjina izmed vas, ki vstopi na šabat, od duhovnikov in od Lévijevcev, boste vratarji vrat,',
        5: 'tretjina bo pri kraljevi hiši in tretjina pri temeljnih velikih vratih, vse ljudstvo pa bo na dvorih Gospodove hiše.',
        6: 'Toda nihče naj ne pride v Gospodovo hišo, razen duhovnikov in tistih, ki služijo od Lévijevcev; oni bodo vstopili, kajti oni so sveti, toda vse ljudstvo bo Gospodova straža.',
        7: 'Lévijevci bodo naokoli obdali kralja, vsak mož s svojim orožjem v svoji roki in kdorkoli drug pride v hišo, bo usmrčen, toda vi bodite s kraljem, ko vstopa in ko gre ven.',
        8: 'Tako so Lévijevci in ves Juda storili glede na vse stvari, ki jih je duhovnik Jojadá zapovedal ter vzeli vsak mož svoje može, ki so vstopali na šabat, s tistimi, ki so na šabat odhajali ven, kajti duhovnik Jojadá ni odpustil skupin.',
        9: 'Poleg tega je duhovnik Jojadá poveljnikom izročil stotine sulic, oklepe in ščite, ki so bili [od] kralja Davida, ki so bili v Božji hiši.',
        10: 'Postavil je vse ljudstvo, vsakega moža s svojim orožjem v svoji roki, od desne strani templja, do leve strani templja, vzdolž oltarja in templja, naokoli kralja.',
        11: 'Potem so privedli ven kraljevega sina in nanj položili krono in mu izročili pričevanje ter ga postavili [za] kralja. Jojadá in njegovi sinovi so ga mazilili ter rekli: »Živel kralj.«',
        12: 'Torej ko je Ataljá zaslišala hrup ljudstva teči in slaviti kralja, je prišla k ljudstvu v Gospodovo hišo.',
        13: 'Pogledala je in glej, kralj je stal pri svojem stebru ob vhodu in princi ter trobente poleg kralja. Vse ljudstvo dežele se je veselilo in trobilo s trobentami, tudi pevci z glasbenimi instrumenti in tisti, ki so učili peti hvalo. Potem je Ataljá pretrgala svoja oblačila in rekla: »Izdaja, izdaja.«',
        14: 'Potem je duhovnik Jojadá privedel ven poveljnike nad stotimi, ki so bili postavljeni nad vojsko in jim rekel: »Odpeljite jo iz dosega in kdorkoli ji sledi, naj bo umorjen z mečem. Kajti duhovnik je rekel: ›Ne umorite je v Gospodovi hiši.‹«',
        15: 'Tako so nanjo položili roke in ko je prišla do vhoda velikih konjskih vrat, ob kraljevi hiši, so jo tam usmrtili.',
        16: 'Jojadá je sklenil zavezo med seboj, med vsem ljudstvom in med kraljem, da bi bili Gospodovo ljudstvo.',
        17: 'Potem je vse ljudstvo odšlo k Báalovi hiši, jo porušilo, razbilo njene oltarje in njene podobe na koščke in pred oltarji usmrtilo Báalovega duhovnika Matána.',
        18: 'Jojadá je določil tudi službe Gospodove hiše po roki Lévijevih duhovnikov, ki jih je David porazdelil v Gospodovi hiši, da darujejo Gospodove žgalne daritve, kakor je to zapisano v Mojzesovi postavi, z razveseljevanjem in prepevanjem, kakor je bilo to odrejeno po Davidu.',
        19: 'Postavil je vratarje pri velikih vratih Gospodove hiše, da nihče, ki je bil nečist v katerikoli stvari, ne bi vstopil.',
        20: 'Vzel je poveljnike izmed stotih, plemiče in voditelje izmed ljudstva in vse ljudstvo dežele ter kralja privedel dol iz Gospodove hiše in prišli so skozi velika vrata v kraljevo hišo ter kralja postavili na prestol kraljestva.',
        21: 'Vse ljudstvo dežele se je veselilo in mesto je bil mirno, potem ko so Ataljo umorili z mečem.',
    },
    24: {
        1: 'Joáš je bil star sedem let, ko je začel kraljevati in v Jeruzalemu je kraljeval štirideset let. Ime njegove matere je bilo Cibja iz Beeršébe.',
        2: 'Joáš je delal to, kar je bilo pravilno v Gospodovih očeh, vse dni duhovnika Jojadája.',
        3: 'Jojadá je zanj vzel dve ženi in zaplodil je sinove in hčere.',
        4: 'Za tem se je pripetilo, da je imel Joáš na srcu, da popravi Gospodovo hišo.',
        5: 'Skupaj je zbral duhovnike in Lévijevce ter jim rekel: »Pojdite ven v Judova mesta in od vsega Izraela zbirajte denar za popravilo hiše svojega Boga iz leta v leto in glejte, da pohitrite zadevo. Vendar Lévijevci niso pohiteli.',
        6: 'Kralj je dal poklicati vodja Jojadája ter mu rekel: »Zakaj nisi od Lévijevcev zahteval, da iz Juda in Jeruzalema prinašajo nabirko, glede na zapoved Mojzesa, Gospodovega služabnika in iz Izraelove skupnosti za šotorsko svetišče pričevanja?',
        7: 'Kajti sinovi te zlobne ženske Atalje so razbili Božjo hišo in tudi vse posvečene stvari Gospodove hiše so podelili Báalom.',
        8: 'Na kraljevo zapoved so naredili zaboj in ga postavili zunaj pri velikih vratih Gospodove hiše.',
        9: 'Naredili so razglas po vsem Judu in Jeruzalemu, naj prinašajo Gospodu nabirko, ki jo je Božji služabnik Mojzes naložil Izraelu v divjini.',
        10: 'Vsi princi in vse ljudstvo se je veselilo, prinašalo in metalo v zaboj, dokler niso končali.',
        11: 'Torej pripetilo se je, da kadar je bil zaboj po roki Lévijevcev prinesen v kraljevo pisarno in ko so videli, da je bilo v njem veliko denarja, sta prišla kraljevi pisar in častnik vélikega duhovnika ter izpraznila zaboj in ga vzela ter ga ponovno odnesla na njegov kraj. Tako so delali dan za dnem in zbrali denarja v obilju.',
        12: 'Kralj in Jojadá sta ga dajala tistim, ki so opravljali delo službe Gospodove hiše ter najemala zidarje in tesarje, da obnovijo Gospodovo hišo in tudi tiste, ki so kovali železo in bron, da popravijo Gospodovo hišo.',
        13: 'Tako so delavci delali in delo dovršili in Božjo hišo so postavili v njeno stanje in jo utrdili.',
        14: 'Ko so jo končali, so preostanek denarja prinesli pred kralja in Jojadája, s čimer so bile narejene posode za Gospodovo hišo, torej posode za služenje in da z njimi darujejo ter žlice in posode iz zlata in srebra. In nenehno so darovali žgalne daritve v Gospodovi hiši, vse Jojadájeve dni.',
        15: 'Toda Jojadá se je postaral in ko je umrl, je bil izpolnjen z dnevi in ko je umrl, je bil star sto trideset let.',
        16: 'Pokopali so ga med kralji v Davidovem mestu, ker je delal dobro v Izraelu, tako za Boga kot za svojo hišo.',
        17: 'Torej po smrti Jojadája so prišli Judovi princi in se globoko priklonili kralju. Potem jim je kralj prisluhnil.',
        18: 'Zapustili so hišo Gospoda, Boga svojih očetov in služili ašeram in malikom in zaradi tega njihovega prekrška je prišel bes nad Juda in Jeruzalem.',
        19: 'Vendar jim je pošiljal preroke, da jih ponovno privedejo h Gospodu in ti so pričevali zoper njih, toda oni jim niso hoteli prisluhnili.',
        20: 'In Božji Duh je prišel nad Zeharjá, sina duhovnika Jojadája, ki je stal nad ljudstvom ter jim rekel: »Tako govori Bog: ›Zakaj prestopate Gospodove zapovedi, da ne morete uspevati? Ker ste zapustili Gospoda, je tudi on zapustil vas.‹«',
        21: 'Oni pa so se zarotili zoper njega in ga na kraljevo zapoved kamnali s kamni na dvoru Gospodove hiše.',
        22: 'Tako se kralj Joáš ni spomnil prijaznosti, ki mu jo je storil njegov oče Jojadá, temveč je usmrtil njegovega sina. In ko je ta umiral, je rekel: » Gospod glej na to in to zahtevaj.«',
        23: 'Pripetilo se je ob koncu leta, da je zoper njega prišla sirska vojska. Prišli so do Juda in Jeruzalema in izmed ljudstva uničili vse prince ljudstva in ves njihov plen poslali h kralju v Damask.',
        24: 'Kajti vojska Sircev je prišla z majhno skupino mož in Gospod je v njihovo roko izročil zelo veliko množico, ker so zapustili Gospoda, Boga svojih očetov. Tako so izvršili sodbo nad Joášem.',
        25: 'Ko so odšli od njega (kajti zapustili so ga v velikih boleznih), so se njegovi lastni služabniki zarotili zoper njega zaradi krvi sinov duhovnika Jojadája in ga usmrtili na njegovi postelji in je umrl. Pokopali so ga v Davidovem mestu, toda niso ga pokopali v mavzolejih kraljev.',
        26: 'To sta tista [dva], ki sta se zarotila zoper njega: Zabád, sin Amónke Šimáte in Jozabád, sin Moábke Šimrite.',
        27: 'Torej glede njegovih sinov in veličine bremen, položenih nadenj in obnove Božje hiše, glej, ta so zapisana v zgodbi knjige kraljev. In namesto njega je zakraljeval njegov sin Amacjá.',
    },
    25: {
        1: 'Amacjá je bil star petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval devetindvajset let. Ime njegove matere je bilo Joadána iz Jeruzalema.',
        2: 'Delal je to, kar je bilo pravilno v Gospodovih očeh, toda ne s popolnim srcem.',
        3: 'Pripetilo se je torej, ko mu je bilo kraljestvo utrjeno, da je usmrtil svoja služabnika, ki sta ubila kralja, njegovega očeta.',
        4: 'Toda njunih otrok ni usmrtil, temveč je storil, kakor je to zapisano v postavi Mojzesove knjige, kjer je Gospod zapovedal, rekoč: ›Očetje ne bodo umrli zaradi otrok niti ne bodo otroci umrli zaradi očetov, temveč bo vsak človek umrl zaradi svojega lastnega greha.‹',
        5: 'Poleg tega je Amacjá zbral skupaj Juda in jih postavil za tisočnike in stotnike, glede na hiše njihovih očetov, po vsem Judu in Benjaminu. Preštel jih je od starosti dvajset let navzgor in jih našel tristo tisoč izbranih mož, zmožnih iti na vojno, ki so lahko zgrabili sulico in ščit.',
        6: 'Najel je tudi sto tisoč močnih junaških mož iz Izraela za sto talentov srebra.',
        7: 'Toda tam je prišel k njemu Božji mož, rekoč: »Oh kralj, naj Izraelova vojska ne gre s teboj, kajti Gospod ni z Izraelom, namreč z vsemi Efrájimovi otroci.',
        8: 'Toda če ti hočeš iti, stori to, bodi močan za bitko. Bog ti bo storil, da padeš pred sovražnikom, kajti Bog ima moč, da pomaga in da podere.«',
        9: 'Amacjá je rekel Božjemu možu: »Toda kaj naj storimo zaradi stotih talentov, ki sem jih dal Izraelovi vojski?« Božji mož je odgovoril: » Gospod ti je zmožen dati veliko več kakor to.«',
        10: 'Potem jih je Amacjá ločil, namreč vojsko, ki je prišla k njemu iz Efrájima, da gre ponovno domov. Zato je bila njihova jeza silno vžgana zoper Juda in domov so se vrnili v veliki jezi.',
        11: 'Amacjá se je okrepil in vodil svoje ljudstvo in odšel v solno dolino in jih izmed Seírovih otrok pobil deset tisoč.',
        12: 'Drugih deset tisoč pa so Judovi otroci pustili žive, jih odvedli ujete in jih privedli na vrh skale ter jih vrgli dol iz vrha skale, da so bili razbiti na koščke.',
        13: 'Toda vojaki vojske, ki jih je Amacjá poslal nazaj, da ne bi šli z njim na bitko, so vpadli na Judova mesta od Samarije celo do Bet Horóna in pobili tri tisoč izmed njih in zajeli veliko plena.',
        14: 'Pripetilo se je torej, potem ko je Amacjá prišel od pokola Edómcev, da je prinesel bogove Seírjevih otrok in jih postavil, da bodo njegovi bogovi, se priklanjal pred njimi in jim zažigal kadilo.',
        15: 'Zato je bila Gospodova jeza vžgana zoper Amacjá in mu je poslal preroka, ki mu je rekel: »Zakaj si iskal za bogovi ljudstva, ki niso mogli rešiti svoje lastno ljudstvo iz tvoje roke?«',
        16: 'Pripetilo se je, ko je govoril z njim, da mu je kralj rekel: »Mar si postavljen za kraljevega svetovalca? Odnehaj. Zakaj bi bil udarjen?« Potem je prerok odnehal in rekel: »Vem, da je Bog določil, da te uniči, ker si to storil in nisi prisluhnil mojemu nasvetu.«',
        17: 'Potem je Judov kralj Amacjá sprejel nasvet in poslal k Jehoášu, Joaházovemu sinu, Jehújevemu sinu, Izraelovemu kralju, rekoč: »Pridi, poglejva drug drugemu v obraz.«',
        18: 'Izraelov kralj Jehoáš pa je poslal k Judovemu kralju Amacjáju, rekoč: »Osat, ki je bil na Libanonu, je poslal k cedri, ki je bila na Libanonu, rekoč: ›Daj svojo hčer mojemu sinu za ženo.‹ In tam mimo je šla divja zver, ki je bila na Libanonu in pomendrala osat.',
        19: 'Ti praviš: ›Glej, udaril si Edómce in tvoje srce te je povzdignilo do bahanja. Ostani torej doma, zakaj bi se vmešaval v svojo bolečino, da bi padel, celó ti in Juda s teboj?‹«',
        20: 'Toda Amacjá ni hotel slišati, kajti to je prišlo od Boga, da bi jih on lahko izročil v roko njihovih sovražnikov, ker so iskali za edómskimi bogovi.',
        21: 'Tako je Izraelov kralj Jehoáš odšel gor in videla sta drug drugega v obraz, tako on in Judov kralj Amacjá, pri Bet Šemešu, ki pripada Judu.',
        22: 'Juda je bil na slabšem pred Izraelom in pobegnili so vsak mož k svojemu šotoru.',
        23: 'Izraelov kralj Jehoáš je prijel Judovega kralja Amacjá, Joáševega sina, Joaházovega sina pri Bet Šemešu in ga privedel v Jeruzalem in porušil jeruzalemsko obzidje od Efrájimovih velikih vrat do vogalnih velikih vrat, štiristo komolcev.',
        24: 'Vzel je vse zlato, srebro in vse posode, ki so bile najdene v Božji hiši z Obéd Edómom in zaklade kraljeve hiše, tudi talce in se vrnil v Samarijo.',
        25: 'Joášev sin Amacjá, kralj Juda, je po smrti Izraelovega kralja, Joaházovega sina Jehoáša, živel petnajst let.',
        26: 'Torej preostala izmed Amacjájevih dejanj, prva in zadnja, glej, mar niso zapisana v knjigi Judovih in Izraelovih kraljev?',
        27: 'Torej po času, ko se je Amacjá odvrnil od sledenja Gospodu, so v Jeruzalemu zoper njega skovali zaroto; on pa je pobegnil v Lahíš. Toda poslali so za njim v Lahíš in ga tam usmrtili.',
        28: 'Pripeljali so ga na konjih in ga pokopali z njegovimi očeti v Judovem mestu.',
    },
    26: {
        1: 'Potem je vse Judovo ljudstvo vzelo Uzíjaha, ki je bil star šestnajst let in ga postavilo [za] kralja namesto njegovega očeta Amacjája.',
        2: 'Pozidal je Elot in ga povrnil Judu, nató je kralj zaspal s svojimi očeti.',
        3: 'Uzíjah je bil star šestnajst let, ko je začel kraljevati in v Jeruzalemu je kraljeval dvainpetdeset let. Ime njegove matere je bilo Jehólja iz Jeruzalema.',
        4: 'Delal je to, kar je bilo pravilno v Gospodovih očeh, glede na vse, kar je delal njegov oče Amacjá.',
        5: 'Iskal je Boga v dneh Zeharjá, ki je imel razumevanje Božjih videnj. Dokler je iskal Gospoda, mu je Bog naredil, da uspeva.',
        6: 'Odšel je naprej in se boril zoper Filistejce in porušil obzidje v Gatu, obzidje v Jabnéju, obzidje v Ašdódu ter zgradil mesta okoli Ašdóda in med Filistejci.',
        7: 'Bog mu je pomagal zoper Filistejce in zoper Arabce, ki prebivajo v Gur Báalu in [zoper] Meunéjce.',
        8: 'Amónci so izročali darila Uzíjahu in njegovo ime se je razširilo celó do vhoda v Egipt, kajti silno se je okrepil.',
        9: 'Poleg tega je Uzíjah zgradil stolpe v Jeruzalemu, pri vogalnih velikih vratih, pri dolinskih velikih vratih in ob vogalu obzidja in jih utrdil.',
        10: 'Prav tako je zgradil stolpe v puščavi in izkopal mnogo vodnjakov, kajti imel je mnogo živine tako v spodnji deželi kakor na ravninah. Tudi poljedelce in obrezovalce vinske trte v gorah in na Karmelu, kajti ljubil je poljedelstvo.',
        11: 'Poleg tega je imel Uzíjah vojsko vojskujočih mož, ki so šli ven, da se vojskujejo po četah, glede na število, po roki pisarja Jeiéla in vladarja Maasejája, pod roko Hananjája, enega izmed kraljevih poveljnikov.',
        12: 'Celotno število vodij očetov močnih junaških mož je bilo dva tisoč šeststo.',
        13: 'Pod njihovo roko je bila vojska, tristo sedem tisoč petsto mož, ki so se bojevali z mogočno močjo, da pomagajo kralju zoper sovražnika.',
        14: 'Uzíjah je zanje po vsej vojski pripravil ščite, sulice, čelade, brezrokavne verižne srajce, loke in prače, da mečejo kamne.',
        15: 'V Jeruzalemu je naredil stroje, ki so jih izumili spretni ljudje, da bi bili na stolpih in na branikih, da streljajo puščice in poleg tega velike kamne. Njegovo ime se je razširilo daleč naokoli, kajti bilo mu je čudovito pomagano, dokler je bil močan.',
        16: 'Toda ko je bil močan, je bilo njegovo srce povzdignjeno k njegovemu uničenju, kajti pregrešil se je zoper Gospoda, svojega Boga in odšel v Gospodov tempelj, da na kadilnem oltarju zažge kadilo.',
        17: 'Duhovnik Azarjá je vstopil za njim in z njim osemdeset Gospodovih duhovnikov, ki so bili hrabri možje.',
        18: 'Zoperstavili so se kralju Uzíjahu in mu rekli: » To ne pripada tebi, Uzíjah, da zažigaš kadilo Gospodu, temveč duhovnikom, Aronovim sinovom, ki so posvečeni, da zažigajo kadilo. Odidi ven iz svetišča, kajti grešil si niti ti to ne bo v tvojo slavo pred Gospodom Bogom.«',
        19: 'Potem je bil Uzíjah ogorčen in v svoji roki je imel kadilnico, da zažiga kadilo. Medtem ko je bil besen nad duhovniki, je celo vstala gobavost na njegovem čelu, pred duhovniki v Gospodovi hiši, poleg kadilnega oltarja.',
        20: 'Véliki duhovnik Azarjá in vsi duhovniki so pogledali nanj in glej, bil je gobav na svojem čelu in sunili so ga proč od tam; da, tudi sam je pohitel, da odide, ker ga je Gospod udaril.',
        21: 'Kralj Uzíjah je bil gobavec do dneva svoje smrti in prebival v posebni hiši, [ker je] bil gobavec, kajti bil je odrezan od Gospodove hiše in njegov sin Jotám je bil nad kraljevo hišo, sodeč ljudstvu dežele.',
        22: 'Torej preostala izmed Uzíjahovih dejanj, prva in zadnja, je zapisal prerok Izaija, Amócov sin.',
        23: 'Tako je Uzíjah zaspal s svojimi očeti in z njegovimi očeti so ga pokopali na pogrebnem polju, ki je pripadalo kraljem, kajti rekli so: »On je gobavec.« Namesto njega je zakraljeval njegov sin Jotám.',
    },
    27: {
        1: 'Jotám je bil star petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let. Ime njegove matere je bilo Jerúša, Cadókova hči.',
        2: 'Delal je to, kar je bilo pravilno v Gospodovih očeh, glede na vse to, kar je delal njegov oče Uzíjah. Vendar ni vstopil v Gospodov tempelj. Ljudstvo pa je še počelo izprijeno.',
        3: 'Zgradil je visoka velika vrata Gospodove hiše in na obzidju Ofele je mnogo gradil.',
        4: 'Poleg tega je zgradil mesta v Judovih gorah in v gozdovih je zgradil gradove in stolpe.',
        5: 'Boril se je tudi s kraljem Amóncev in prevladal zoper njih. Amónovi otroci so mu isto leto dali sto talentov srebra, sto tisoč mer pšenice in deset tisoč [mer] ječmena. Toliko so mu Amónovi otroci plačali tako drugo leto kakor tretje leto.',
        6: 'Tako je Jotám postal mogočen, ker je pripravil svoje poti pred Gospodom, svojim Bogom.',
        7: 'Torej preostala izmed Jotámovih dejanj in vse njegove vojne in njegove poti, glej, zapisane so v knjigi Izraelovih in Judovih kraljev.',
        8: 'Star je bil petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let.',
        9: 'Jotám je zaspal s svojimi očeti in pokopali so ga v Davidovem mestu in namesto njega je zakraljeval njegov sin Aház.',
    },
    28: {
        1: 'Aház je bil star dvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval šestnajst let, toda ni delal tega, kar je bilo pravilno v Gospodovih očeh, kakor njegov oče David.',
        2: 'Kajti hodil je po poteh Izraelovih kraljev in prav tako je naredil ulite podobe za Báale.',
        3: 'Poleg tega je zažigal kadilo v dolini Hinómovega sina in svoje otroke sežigal v ognju, po ogabnostih poganov, ki jih je Gospod pregnal pred Izraelovimi otroki.',
        4: 'Tudi daroval je in zažigal kadilo na visokih krajih, na hribih in pod vsakim zelenim drevesom.',
        5: 'Zato ga je Gospod, njegov Bog, izročil v roko sirskega kralja in udarili so ga in izmed njih odvedli veliko množico ujetnikov in jih privedli v Damask. Izročen je bil tudi v roko Izraelovega kralja, ki ga je udaril z velikim pokolom.',
        6: 'Kajti Remaljájev sin Pékah jih je v Judu v enem dnevu ubil sto dvajset tisoč, ki so bili vsi hrabri možje, ker so zapustili Gospoda, Boga svojih očetov.',
        7: 'Zihrí, mogočen mož iz Efrájima, je usmrtil kraljevega sina Maasejája, voditelja hiše Azrikáma in Elkanája, ki je bil poleg kralja.',
        8: 'Izraelovi otroci so odvedli ujetnike izmed njihovih bratov, dvesto tisoč žensk, sinov in hčera ter od njih odvzeli tudi mnogo plena in plen prinesli v Samarijo.',
        9: 'Toda tam je bil Gospodov prerok, katerega ime je bilo Odéd in ta je šel ven pred vojsko, ki je prišla do Samarije ter jim rekel: »Glejte, ker je bil Gospod, Bog vaših očetov, besen na Juda, jih je izročil v vašo roko in vi ste jih umorili v besnenju, ki sega do nebes.',
        10: 'In sedaj ste se namenili, da obdržite Judove in jeruzalemske otroke, podrejene sebi za sužnje in sužnjice. Toda ali niso z vami, celo z vami, grehi zoper Gospoda, vašega Boga?',
        11: 'Sedaj me torej poslušajte in ponovno osvobodite ujetnike, ki ste jih zajeli izmed svojih bratov, kajti nad vami je ogorčen Gospodov bes.',
        12: 'Potem so nekateri izmed poglavarjev Efrájimovih otrok, Johanánov sin Azarjá, Mešilemótov sin Berehjá, Šalúmov sin Hizkijá in Hadlájev sin Amasá vstali zoper tiste, ki so prišli iz vojne',
        13: 'ter jim rekli: »Ujetnikov ne boste privedli sèm, kajti kakor smo že grešili zoper Gospoda, ste se vi namenili, da dodate še več k našim grehom in k našemu prestopku, kajti naš prestopek je velik in zoper Izraela je ogorčen bes.',
        14: 'Tako so oboroženi možje pustili ujetnike in plen pred princi in pred vso skupnostjo.',
        15: 'Možje, ki so bili določeni po imenu, so vstali, vzeli ujetnike in s plenom oblekli vse, ki so bili med njimi nagi, jih odeli, obuli, jim dali jesti in piti ter jih mazilili in vse slabotne med njimi odvedli na oslih ter jih privedli do Jerihe, mesta palmovih dreves, do njihovih bratov. Potem so se vrnili v Samarijo.',
        16: 'Ob tistem času je kralj Aház poslal k asirskim kraljem, da mu pomagajo.',
        17: 'Kajti Edómci so ponovno prišli in udarili Juda in odvedli ujetnike.',
        18: 'Filistejci so vdrli tudi v mesta spodnje dežele in jug Juda in zavzeli Bet Šemeš, Ajalón, Gederót, Sohó in njegove vasi, Timno z njenimi vasmi, tudi Gimzó in njegove vasi in tam prebivali.',
        19: 'Kajti Gospod je ponižal Juda zaradi Izraelovega kralja Aháza, kajti ta je slekel Juda in se hudo pregrešil zoper Gospoda.',
        20: 'K njemu je prišel asirski kralj Tiglát Pilnéser in ga stiskal, toda ni ga okrepil.',
        21: 'Kajti Aház je odvzel delež iz Gospodove hiše in iz kraljeve hiše in od princev in to dal asirskemu kralju, toda ta mu ni pomagal.',
        22: 'V času svoje stiske je še bolj grešil zoper Gospoda. To je ta kralj Aház.',
        23: 'Kajti žrtvoval je bogovom Damaska, ki so ga udarili in rekel: »Ker so jim pomagali bogovi sirskih kraljev, zato bom žrtvoval njim, da bi mi lahko pomagali.« Toda oni so bili propad njemu in vsemu Izraelu.',
        24: 'Aház je zbral skupaj posode iz Božje hiše, razbil na koščke posode iz Božje hiše in zaprl vrata Gospodove hiše ter si naredil oltarje na vsakem jeruzalemskem vogalu.',
        25: 'V vsakem posameznem Judovem mestu je postavil visoke kraje, da zažigajo kadilo drugim bogovom in do jeze dražijo Gospoda, Boga svojih očetov.',
        26: 'Torej ostala njegova dela in vse njegove poti, prve in zadnje, glej, zapisane so v knjigi Judovih in Izraelovih kraljev.',
        27: 'Aház je zaspal s svojimi očeti in pokopali so ga v mestu, torej v Jeruzalemu. Toda niso ga prinesli v mavzoleje Izraelovih kraljev. Namesto njega je zakraljeval njegov sin Ezekíja.',
    },
    29: {
        1: 'Ezekíja je začel vladati, ko je bil star petindvajset let in v Jeruzalemu je vladal devetindvajset let. Ime njegove matere je bilo Abíja, Zeharjájeva hči.',
        2: 'Delal je, kar je bilo pravilno v Gospodovih očeh, glede na vse to, kar je storil njegov oče David.',
        3: 'V prvem letu svojega vladanja, v prvem mesecu, je odprl vrata Gospodove hiše in jih popravil.',
        4: 'Pripeljal je duhovnike in Lévijevce ter jih skupaj zbral na vzhodni ulici',
        5: 'ter jim rekel: »Poslušajte me, vi Lévijevci, sedaj se posvetite in posvetite hišo Gospoda, Boga svojih očetov in odnesite umazanost iz svetega kraja.',
        6: 'Kajti naši očetje so grešili in naredili to, kar je bilo zlo v očeh Gospoda, našega Boga, ga zapustili in svoje obraze obrnili proč od Gospodovega prebivališča in obrnili svoje hrbte.',
        7: 'Prav tako so zaprli vrata preddverja in ugasili svetilke in niso zažigali kadila niti darovali žgalnih daritev Izraelovemu Bogu na svetem kraju.',
        8: 'Zato je bil Gospodov bes nad Judom in Jeruzalemom in izročil jih je v težavo, osuplost in posmeh, kakor vidite s svojimi očmi.',
        9: 'Kajti, glejte, naši očetje so padli pod mečem, naši sinovi, naše hčere in naše žene so zaradi tega v ujetništvu.',
        10: 'Sedaj je na mojem srcu, da sklenem zavezo z Gospodom, Izraelovim Bogom, da se njegov kruti bes lahko odvrne od nas.',
        11: 'Moji sinovi, ne bodite sedaj nemarni, kajti Gospod vas je izbral, da stojite pred njim, da mu služite in da bi mu služili in zažigali kadilo.',
        12: 'Potem so vstali Lévijevci: Amasájev sin Mahat in Azarjájev sin Joél izmed sinov Kehátovcev; izmed Meraríjevih sinov Abdíjev sin Kiš in Jehalelélov sin Azarjá; izmed Geršóncev Zimájev sin Joáh in Joáhov sin Eden;',
        13: 'izmed Elicafánovih sinov Šimríj in Jeiél; izmed Asáfovih sinov Zeharjá in Matanjá;',
        14: 'izmed Hemánovih sinov Jehiél in Šimí in izmed Jedutúnovih sinov Šemajája in Uziél.',
        15: 'Zbrali so svoje brate, se posvetili in prišli glede na kraljevo zapoved, po Gospodovih besedah, da očistijo Gospodovo hišo.',
        16: 'Duhovniki so odšli v notranji del Gospodove hiše, da jo očistijo in ven prinesejo vso nečistost, ki jo najdejo v Gospodovem templju, na dvoru Gospodove hiše. In Lévijevci so to vzeli, da to odnesejo ven, v potok Kidron.',
        17: 'Torej posvečevati so začeli na prvi dan prvega meseca in na osmi dan meseca so prišli do Gospodovega preddverja. Tako so v osmih dneh posvetili Gospodovo hišo in na šestnajsti dan prvega meseca so dokončali.',
        18: 'Potem so odšli h kralju Ezekíju in rekli: »Očistili smo vso Gospodovo hišo in oltar žgalne daritve, z vsemi njegovimi posodami in mizo hlebov navzočnosti, z vsemi njenimi posodami.',
        19: 'Poleg tega smo pripravili in posvetili vse posode, ki jih je kralj Aház ob svojem kraljevanju v svojem prestopku zavrgel. Glej, pred Gospodovim oltarjem so.',
        20: 'Potem se je kralj Ezekíja zgodaj dvignil in zbral voditelje mesta ter odšel gor h Gospodovi hiši.',
        21: 'Privedli so sedem bikcev, sedem ovnov, sedem jagnjet in sedem kozlov za daritev za greh za kraljestvo, za svetišče in za Juda. Duhovnikom, Aronovim sinovom, je zapovedal, da jih darujejo na Gospodovem oltarju.',
        22: 'Tako so zaklali bikce in duhovniki so prestregli kri in jo poškropili na oltar. Tudi ko so zaklali ovne, so na oltar poškropili kri. Zaklali so tudi jagnjeta in na oltar poškropili kri.',
        23: 'Pred kralja in skupnost so privedli kozle za daritev za greh in ti so svoje roke položili nanje.',
        24: 'Duhovniki so jih zaklali in naredili pobotanje z njihovo krvjo na oltarju, da opravijo odkupitev za ves Izrael, kajti kralj je zapovedal, da naj bo za ves Izrael narejena žgalna daritev in daritev za greh.',
        25: 'V Gospodovi hiši je postavil Lévijevce s cimbalami, plunkami in harfami, glede na Davidovo zapoved in [glede na zapoved] Gada, kraljevega vidca in preroka Natána, kajti taka je bila Gospodova zapoved po njegovih prerokih.',
        26: 'Lévijevci so stali z Davidovimi glasbili in duhovniki s trobentami.',
        27: 'Ezekíja je zapovedal, da na oltarju darujejo žgalno daritev. Ko se je žgalna daritev začela, se je začela tudi Gospodova pesem s trobentami in z glasbili, ki jih je določil Izraelov kralj David.',
        28: 'Vsa skupnost je oboževala in pevci so peli in trobentači so trobili. In vse to se je nadaljevalo, dokler ni bila dokončana žgalna daritev.',
        29: 'Ko so prenehali z daritvijo, so se kralj in vsi tisti, ki so bili prisotni z njim, priklonili in oboževali.',
        30: 'Poleg tega so kralj Ezekíja in princi zapovedali Lévijevcem, da prepevajo hvalo Gospodu z besedami Davida in vidca Asáfa. In z veseljem so peli hvalnice, sklonili svoje glave in oboževali.',
        31: 'Potem je Ezekíja odgovoril in rekel: »Sedaj ste se uméstili Gospodu, pridite bliže in prinesite klavne daritve in zahvalne daritve v Gospodovo hišo.« In skupnost je prinesla klavne daritve in zahvalne daritve in toliko, kot jih je bilo voljnega srca, žgalne daritve.',
        32: 'Število žgalnih daritev, ki jih je prinesla skupnost, je bilo sedemdeset bikcev, sto ovnov in dvesto jagnjet. Vsi ti so bili za žgalno daritev Gospodu.',
        33: 'Posvečenih stvari je bilo šeststo volov in tri tisoč ovc.',
        34: 'Toda duhovnikov je bilo premalo, tako da niso mogli odreti vseh žgalnih daritev, zato so jim pomagali njihovi bratje Lévijevci, dokler ni bilo delo končano in dokler se niso posvetili drugi duhovniki, kajti Lévijevci so bili bolj iskreni v srcu, da se posvetijo, kakor duhovniki.',
        35: 'Tudi žgalnih daritev je bilo v obilju, s tolščo mirovnih daritev in pitnih daritev za vsako žgalno daritev. Tako je bila služba Gospodove hiše urejena.',
        36: 'Ezekíja se je veselil in vse ljudstvo, da je Bog pripravil ljudstvo, kajti stvar je bila storjena nenadoma.',
    },
    30: {
        1: 'Ezekíja je poslal k vsemu Izraelu in Judu in napisal tudi pisma Efrájimu in Manáseju, da naj pridejo h Gospodovi hiši v Jeruzalemu, da praznujejo pasho Gospodu, Izraelovemu Bogu.',
        2: 'Kajti kralj je sprejel nasvet in njegovi princi in vsa skupnost v Jeruzalemu, da v drugem mesecu praznujejo pasho.',
        3: 'Kajti niso je mogli imeti ob tistem času, ker se duhovniki niso zadosti posvetili niti se ljudstvo ni zbralo skupaj k Jeruzalemu.',
        4: 'Stvar je ugajala kralju in vsej skupnosti.',
        5: 'Tako so potrdili odlok, da ga razglasijo po vsem Izraelu, od Beeršébe, celo do Dana, da bi prišli praznovat pasho Gospodu, Izraelovemu Bogu, v Jeruzalemu, kajti že dolgo časa tega niso storili na takšen način, kot je bilo to napisano.',
        6: 'Tako so tekači odšli s pismi kralja in njegovih princev po vsem Izraelu in Judu in glede na kraljevo zapoved, rekoč: »Vi, Izraelovi otroci, se ponovno obrnite h Gospodu, Bogu Abrahama, Izaka in Izraela in on se bo obrnil k preostanku izmed vas, ki ste pobegnili iz roke asirskih kraljev.',
        7: 'Vi pa ne bodite podobni svojim očetom in svojim bratim, ki so grešili zoper Gospoda, Boga svojih očetov, ki jih je zato izročil v opustošenje, kakor vidite.',
        8: 'Torej ne bodite trdovratni, kakor so bili vaši očetje, temveč se uklonite Gospodu in vstopite v njegovo svetišče, ki ga je posvetil na veke, in služite Gospodu, svojemu Bogu, da se okrutnost njegovega besa lahko odvrne od vas.',
        9: 'Kajti če se ponovno obrnete h Gospodu, bodo vaši bratje in vaši otroci našli sočutje pred tistimi, ki jih vodijo ujete, tako da se bodo ponovno vrnili v to deželo, kajti Gospod, vaš Bog, je usmiljen in milostljiv in svojega obraza ne bo odvrnil od vas, če se vi vrnete k njemu.',
        10: 'Tako je pošta šla od mesta do mesta po vsej deželi, od Efrájima in Manáseja, celo do Zábulona, toda smejali so se jim do norčevanja in jih zasmehovali.',
        11: 'Kljub temu so se številni izmed Aserja, Manáseja in Zábulona ponižali in prišli v Jeruzalem.',
        12: 'Tudi v Judu je bila Božja roka, da jim da eno srce, da po Gospodovi besedi storijo zapoved kralja in princev.',
        13: 'V Jeruzalemu se je zbralo mnogo ljudstva, zelo velika skupnost, da bi v drugem mesecu praznovali praznik nekvašenega kruha.',
        14: 'Vzdignili so se in odnesli oltarje, ki so bili v Jeruzalemu in vse kadilne oltarje so odnesli proč in jih vrgli v potok Kidron.',
        15: 'Potem so na štirinajsti dan drugega meseca zaklali pasho. Duhovniki in Lévijevci so bili osramočeni in se posvetili in prinesli so žgalne daritve v Gospodovo hišo.',
        16: 'Stali so na svojem mestu, po njihovem običaju, glede na postavo Mojzesa, Božjega moža. Duhovniki so poškropili kri, ki so jo prejeli iz rok Lévijevcev.',
        17: 'Kajti v skupnosti so bili številni, ki niso bili posvečeni, zato so bili Lévijevci zadolženi za zakol pashe za vsakogar, ki ni bil čist, da jih posvetijo Gospodu.',
        18: 'Kajti množica ljudstva, celó številni izmed Efrájima, Manáseja, Isahárja in Zábulona se niso očistili, vendar so jedli pasho drugače, kot je bilo napisano. Toda Ezekíja je molil zanje, rekoč: »Dobri Gospod naj odpusti vsakomur,',
        19: 'ki pripravlja svoje srce, da išče Boga, Gospoda Boga svojih očetov, čeprav ni očiščen glede na očiščevanje svetišča.«',
        20: 'Gospod je prisluhnil Ezekíju ter ozdravil ljudstvo.',
        21: 'Izraelovi otroci, ki so bili prisotni v Jeruzalemu, so z velikim veseljem sedem dni imeli praznik nekvašenega kruha. Lévijevci in duhovniki so dan za dnem hvalili Gospoda, pojoč Gospodu z glasnimi glasbili.',
        22: 'Ezekíja je tolažilno govoril vsem Lévijevcem, ki so učili dobrega Gospodovega spoznanja. Jedli so vseh sedem prazničnih dni, žrtvovali mirovne daritve in delali priznanje Gospodu, Bogu svojih očetov.',
        23: 'Celoten zbor se je posvetoval, da praznuje [še] drugih sedem dni. In z veseljem so praznovali [še] drugih sedem dni.',
        24: 'Kajti Judov kralj Ezekíja je dal skupnosti tisoč bikcev in sedem tisoč ovc, in princi so dali skupnosti tisoč bikcev in deset tisoč ovc. In veliko število duhovnikov se je posvetilo.',
        25: 'Vsa Judova skupnost, z duhovniki in Lévijevci in ves zbor, ki je prišel iz Izraela in tujci, ki so prišli iz Izraelove dežele in tisti, ki so prebivali v Judu, so se veselili.',
        26: 'Tako je bila v Jeruzalemu velika radost, kajti od časa Salomona, Davidovega sina, Izraelovega kralja, ni bilo v Jeruzalemu ničesar podobnega.',
        27: 'Potem so duhovniki, Lévijevci, vstali, blagoslovili ljudstvo in njihov glas je bil slišan in njihova molitev je prišla gor do njegovega svetega prebivališča, celó do nebes.',
    },
    31: {
        1: 'Torej, ko je bilo vse to končano, je ves Izrael, ki je bil prisoten, odšel ven v Judova mesta in na koščke so razbili podobe, posekali ašere, podrli visoke kraje in oltarje iz vsega Juda in Benjamina, tudi v Efrájimu in Manáseju, dokler niso vseh uničili do konca. Potem so se vsi Izraelovi otroci vrnili, vsak mož k svoji posesti, v svoja lastna mesta.',
        2: 'Ezekíja je določil skupine duhovnikov in Lévijevce po njihovih skupinah, vsakega moža glede na njegovo službo, duhovnike in Lévijevce, da služijo za žgalne daritve in za mirovne daritve, da se zahvaljujejo in da hvalijo v velikih vratih Gospodovih šotorov.',
        3: 'Določil je tudi kraljev delež njegovega imetja za žgalne daritve, namreč za jutranje in večerne žgalne daritve, za šabatne žgalne daritve, za mlaje in za določene praznike, kakor je to zapisano v Gospodovi postavi.',
        4: 'Poleg tega je zapovedal ljudstvu, ki je prebivalo v Jeruzalemu, naj dajo delež duhovnikom in Lévijevcem, da bi bili lahko ohrabreni v Gospodovi postavi.',
        5: 'Takoj, ko je bila zapoved razglašena, so Izraelovi otroci v obilju prinašali prvih sadov od žita, vina, olja, meda in od vsega donosa iz polja. Desetino od vseh stvari so prinašali v obilju.',
        6: 'Glede otrok iz Izraela in Juda, ki so prebivali v Judovih mestih, so tudi oni privedli desetino od volov in ovc in desetino od svetih stvari, ki so bile posvečene Gospodu, njihovemu Bogu in jih nalagali po kupih.',
        7: 'V tretjem mesecu so začeli polagati temelj kupom in jih dokončali v sedmem mesecu.',
        8: 'Ko so Ezekíja in princi prišli in videli kupe, so blagoslovili Gospoda in njegovo ljudstvo Izrael.',
        9: 'Potem je Ezekíja z duhovniki in Lévijevci spraševal glede teh kupov.',
        10: 'Véliki duhovnik Azarjá iz Cadókove hiše mu je odgovoril in rekel: »Odkar je ljudstvo začelo prinašati daritve v Gospodovo hišo, smo imeli dovolj za jesti in obilje je preostalo, kajti Gospod je blagoslovil svoje ljudstvo in to, kar je ostalo, je ta velika zaloga.«',
        11: 'Potem je Ezekíja zapovedal, da pripravijo sobe v Gospodovi hiši in pripravili so jih',
        12: 'in vanje so zvesto prinašali daritve, desetine in posvečene stvari, nad katerimi je bil poveljnik, Lévijevec Konanjá in njegov brat Šimí je bil naslednji.',
        13: 'Jehiél, Azazjá, Nahat, Asaél, Jerimót, Jozabád, Eliél, Jismahjá, Mahat in Benajá so bili nadzorniki pod roko Konanjája in njegovega brata Šimíja na zapoved kralja Ezekíja in Azarjája, poveljnika Božje hiše.',
        14: 'Koré, sin Lévijevca Jimnáha, vratar proti vzhodu, je bil nad prostovoljnimi daritvami Bogu, da razdeljuje daritve Gospodu in najsvetejše stvari.',
        15: 'Poleg njega so bili Eden, Minjamín, Ješúa, Šemajá, Amarjá in Šehanjá v mestih duhovnikov, v svoji določeni službi, da dajo svojim bratom po skupinah, tako velikim kakor malim,',
        16: 'poleg njihovega rodovnika moških, starih od treh let in navzgor, celó vsak, kdor vstopa v Gospodovo hišo, njegov dnevni delež za njihovo službo po njihovih zadolžitvah, glede na njihove skupine.',
        17: 'Tako rodovnikom duhovnikov po hiši njihovih očetov kot Lévijevcem od dvajsetih let starosti in navzgor po njihovih zadolžitvah, po njihovih skupinah.',
        18: 'In rodovnikom vseh njihovih malčkov, njihovih žen, njihovih sinov in njihovih hčera po vsej skupnosti, kajti v njihovi določeni službi so se posvetili v svetosti.',
        19: 'Tudi od sinov duhovnika Arona, ki so bili na poljih predmestij njihovih mest v vsakem posameznem mestu, možje, ki so bili določeni po imenu, da dajo deleže vsem moškim med duhovniki in vsem, ki so bili po rodovnikih prešteti med Lévijevci.',
        20: 'Tako je storil Ezekíja po vsem Judu in delal to, kar je bilo dobro, pravilno in resnično pred Gospodom, svojim Bogom.',
        21: 'V vsakem delu, ki ga je začel v službi Božje hiše, v postavi in v zapovedih, da išče svojega Boga, je to počel z vsem svojim srcem in uspeval.',
    },
    32: {
        1: 'Po teh stvareh in ustanovitvi tega je prišel asirski kralj Senaherib, vstopil v Juda, se utaboril zoper utrjena mesta in mislil, da jih osvoji zase.',
        2: 'Ko je Ezekíja videl, da je Senaherib prišel in da se je namenil, da se bojuje zoper Jeruzalem,',
        3: 'se je posvetoval s svojimi princi in svojimi mogočnimi možmi, da zamaši vodne studence, ki so bili zunaj mesta, in ti so mu pomagali.',
        4: 'Tako je bilo tam skupaj zbranih veliko ljudi, ki so zamašili vse studence in potok, ki je tekel čez sredo dežele, rekoč: »Zakaj bi prišli asirski kralji in našli mnogo vode?«',
        5: 'Prav tako se je okrepil in pozidal vse obzidje, ki je bil porušeno in ga dvignil k stolpom in drugi zid zunaj in popravil Miló v Davidovem mestu ter naredil puščic in ščitov v obilju.',
        6: 'Nad ljudstvom je postavil vojne poveljnike in jih zbral skupaj k sebi na ulici velikih vrat mesta in jim tolažilno govoril, rekoč:',
        7: '»Bodite močni in pogumni, ne bodite prestrašeni niti zaprepadeni zaradi asirskega kralja niti zaradi vse množice, ki je z njim, kajti z nami jih je več kakor z njim.',
        8: 'Z njim je mesen laket, toda z nami je Gospod, naš Bog, da nam pomaga in da bori naše bitke.« In ljudstvo se je opiralo na besede Judovega kralja Ezekíja.',
        9: 'Za tem je asirski kralj Senaherib poslal svoje služabnike v Jeruzalem, (toda on sam je oblegal Lahíš in vsa njegova moč z njim) k Judovemu kralju Ezekíju in vsemu Judu, ki so bili v Jeruzalemu, rekoč:',
        10: '»Tako govori asirski kralj Senaherib: ›Komu zaupate, da ostajate v obleganem Jeruzalemu?',
        11: 'Mar vas Ezekija ne prepričuje, da bi se prepustili smrti zaradi lakote in žeje, rekoč: › Gospod, naš Bog, nas bo osvobodil iz roke asirskega kralja?‹',
        12: 'Mar ni isti Ezekíja odstranil njegove visoke kraje in njegove oltarje ter zapovedal Judu in Jeruzalemu, rekoč: ›Oboževali boste pred enim oltarjem in na njem zažigali kadilo?‹',
        13: 'Ne veste, kaj smo jaz in moji očetje storili vsem ljudstvom drugih dežel? Mar so bili bogovi narodov tistih dežel kakorkoli zmožni svoje dežele osvoboditi iz moje roke?',
        14: 'Kdo je bil tam med vsemi bogovi tistih narodov, ki so jih moji očetje popolnoma uničili, ki bi lahko osvobodil svoje ljudstvo iz moje roke, da bi vas bil vaš Bog zmožen osvoboditi iz moje roke?',
        15: 'Zdaj torej naj vas Ezekíja ne zavede niti pregovori o tej zadevi niti mu še ne verjemite, kajti noben bog iz kateregakoli naroda ali kraljestva ni bil zmožen osvoboditi svojega ljudstva iz moje roke in iz roke mojih očetov. Kako veliko manj vas bo vaš Bog osvobodil iz moje roke?«',
        16: 'Njegovi služabniki so še bolj govorili zoper Gospoda Boga in zoper njegovega služabnika Ezekíja.',
        17: 'Napisal je tudi pisma, da udriha po Gospodu, Izraelovemu Bogu in da govori zoper njega, rekoč: »Kakor bogovi narodov drugih dežel niso osvobodili svojih ljudstev iz moje roke, tako Ezekíjev Bog ne bo osvobodil svojega ljudstva iz moje roke.«',
        18: 'Potem so z močnim glasom zaklicali v Judovskem jeziku jeruzalemskemu ljudstvu, ki so bili na obzidju, da jih prestrašijo in da jih vznemirijo, da bi lahko zavzeli mesto.',
        19: 'Govorili so zoper jeruzalemskega Boga kakor zoper bogove ljudstev zemlje, ki so bili delo človeških rok.',
        20: 'Zaradi tega razloga sta kralj Ezekíja in prerok Izaija, Amócov sin, molila in klicala k nebu.',
        21: 'In Gospod je poslal angela, ki je usmrtil vse močne junaške može ter voditelje in poveljnike v taboru asirskega kralja. Tako se je ta z osramočenim obrazom vrnil k svoji lastni deželi. Ko pa je prišel v hišo svojega boga, sta ga tam z mečem usmrtila tista [dva], ki sta prišla iz njegovih lastnih ledij.',
        22: 'Tako je Gospod rešil Ezekíja in prebivalce Jeruzalema iz roke asirskega kralja Senaheriba in iz roke vseh drugih ter jih usmerjal na vsaki strani.',
        23: 'Mnogi so Gospodu prinašali darila v Jeruzalem in darila Judovemu kralju Ezekíju, tako da je bil od takrat naprej poveličan v očeh vseh narodov.',
        24: 'V tistih dneh je bil Ezekíja na smrt bolan in molil h Gospodu in ta mu je spregovoril ter mu dal znamenje.',
        25: 'Toda Ezekíja ni povrnil glede na korist, izkazano njemu, kajti njegovo srce je bilo povzdignjeno. Zato je bil bes nad njim, nad Judom in [nad] Jeruzalemom.',
        26: 'Vendar se je Ezekíja ponižal zaradi ošabnosti svojega srca, tako on kakor prebivalci Jeruzalema, tako da v Ezekíjevih dneh Gospodov bes ni prišel nadnje.',
        27: 'Ezekíja je imel silno veliko bogastev in časti. Naredil si je zakladnice za srebro, zlato, dragocene kamne, dišave, ščite in za vse vrste prijetnih dragocenosti;',
        28: 'tudi skladišča za donos od žita, vina in olja in hleve za vse vrste živali in staje za trope.',
        29: 'Poleg tega si je priskrbel mesta, posesti tropov in čred v obilju, kajti Bog mu je dal zelo veliko imetja.',
        30: 'Ta isti Ezekíja je tudi ustavil gornji vodni tok Gihona in ga privedel naravnost dol k zahodni strani Davidovega mesta. Ezekíja je uspeval v vseh svojih delih.',
        31: 'Vendar ga je v zadevi predstavnikov babilonskih princev, ki so poslali k njemu, da povprašajo o čudežu, ki je bil storjen v deželi, Bog zapustil, da ga preizkusi, da bi lahko spoznal vse, kar je bilo v njegovem srcu.',
        32: 'Torej preostala izmed Ezekíjevih dejanj in njegova dobrota, glej, zapisana so v videnju preroka Amócovega sina Izaija ter v knjigi Judovih in Izraelovih kraljev.',
        33: 'Ezekíja je zaspal s svojimi očeti in pokopali so ga v glavnem izmed mavzolejev Davidovih sinov. Ves Juda in prebivalci Jeruzalema so mu ob njegovi smrti izkazali čast. Namesto njega je zakraljeval njegov sin Manáse.',
    },
    33: {
        1: 'Manáse je bil star dvanajst let, ko je začel kraljevati in v Jeruzalemu je kraljeval petinpetdeset let,',
        2: 'toda počel je to, kar je bilo zlo v Gospodovih očeh, podobno ogabnostim poganov, ki jih je Gospod pregnal pred Izraelovimi otroki.',
        3: 'Kajti ponovno je zgradil visoke kraje, ki jih je njegov oče Ezekíja porušil, vzdignil Báalove oltarje, naredil ašere in oboževal vso vojsko neba ter jim služil.',
        4: 'Prav tako je zgradil oltarje v Gospodovi hiši, o kateri je Gospod rekel: »V Jeruzalemu bo moje ime na veke.«',
        5: 'Zgradil je oltarje za vso vojsko neba v dveh dvorih Gospodove hiše.',
        6: 'Svoje otroke je izročil, da gredo skozi ogenj v dolini sina Hinómovega. Obeleževal je tudi čase, uporabljal izrekanje urokov, uporabljal čarovništvo in postopal z osebnim duhom in s čarovniki. Storil je mnogo zla v Gospodovih očeh, da ga izziva do jeze.',
        7: 'Postavil je izrezljano podobo, malika, ki ga je naredil v Božji hiši, o kateri je Bog rekel Davidu in njegovemu sinu Salomonu: »V tej hiši, v Jeruzalemu, ki sem jo izbral pred vsemi Izraelovimi rodovi, bom svoje ime postavil na veke.',
        8: 'Niti ne bom več odstranil Izraelovega stopala iz dežele, ki sem jo določil za vaše očete, tako da bodo pazili, da storijo vse, kar sem jim zapovedal, glede na celotno postavo, zakone in odredbe po Mojzesovi roki.',
        9: 'Tako je Manáse storil Judu in prebivalcem Jeruzalema, da zaidejo in da počnejo huje kakor pogani, ki jih je Gospod uničil pred Izraelovimi otroki.',
        10: 'Gospod je spregovoril Manáseju in njegovemu ljudstvu, toda niso hoteli prisluhniti.',
        11: 'Zato je Gospod nadnje privedel poveljnike vojske asirskega kralja, ki so Manáseja zajeli med trnjem in ga zvezali z okovi ter ga odvedli v Babilon.',
        12: 'Ko je bil v stiski, je iskal Gospoda, svojega Boga in se silno ponižal pred Bogom svojih očetov',
        13: 'in molil k njemu in izprošen je bil od njega in slišal je njegovo ponižno prošnjo in ga ponovno privedel k Jeruzalemu, v njegovo kraljestvo. Potem je Manáse spoznal, da je bil Gospod Bog.',
        14: 'Torej po tem je zgradil zid zunaj Davidovega mesta, na zahodni strani Gihona, v dolini, celo pri vhodu velikih ribjih vrat in obdal Ofel ter ga dvignil na zelo veliko višino in vojne poveljnike postavil v vsa utrjena Judova mesta.',
        15: 'Odstranil je tuje bogove in malike iz Gospodove hiše in vse oltarje, ki jih je zgradil na gori Gospodove hiše in v Jeruzalemu ter jih vrgel iz mesta.',
        16: 'Popravil je Gospodov oltar in na njem žrtvoval mirovne daritve in zahvalne daritve in Judu zapovedal, da služi Gospodu, Izraelovemu Bogu.',
        17: 'Kljub temu je ljudstvo še vedno darovalo na visokih krajih, vendar samo Gospodu, svojemu Bogu.',
        18: 'Torej preostala izmed Manásejevih dejanj, njegova molitev k njegovemu Bogu in besede vidcev, ki so mu govorili v imenu Gospoda, Izraelovega Boga, glej, ta so zapisana v knjigi Izraelovih kraljev.',
        19: 'Tudi njegova molitev in kako je bil Bog izprošen od njega, ves njegov greh, njegov prekršek in kraji, na katerih si je zgradil visoke kraje ter postavil ašere in rezane podobe, preden je bil ponižan. Glej, ta so zapisana med izreki vidcev.',
        20: 'Tako je Manáse zaspal s svojimi očeti in pokopali so ga v njegovi lastni hiši. Namesto njega je zakraljeval njegov sin Amón.',
        21: 'Amón je bil star dvaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval dve leti.',
        22: 'Toda počel je to, kar je bilo zlo v Gospodovih očeh, kakor je počel njegov oče Manáse, kajti Amón je žrtvoval vsem izrezljanim podobam, ki jih je naredil njegov oče Manáse in jim služil.',
        23: 'Ni se ponižal pred Gospodom, kakor se je ponižal njegov oče Manáse, temveč je Amón bolj in bolj grešil.',
        24: 'In njegovi služabniki so se zarotili zoper njega in ga usmrtili v njegovi lastni hiši.',
        25: 'Toda ljudstvo dežele je usmrtilo vse tiste, ki so se zarotili zoper kralja Amóna in ljudstvo dežele je postavilo njegovega sina Jošíja za kralja namesto njega.',
    },
    34: {
        1: 'Jošíja je bil star osem let, ko je začel kraljevati in v Jeruzalemu je kraljeval enaintrideset let.',
        2: 'Delal je to, kar je bilo pravilno v Gospodovih očeh in hodil po poteh svojega očeta Davida in se ni nagnil niti k desni roki niti k levi.',
        3: 'Kajti v osmem letu svojega kraljevanja, ko je bil še mlad, je začel iskati Boga svojega očeta Davida in v dvanajstem letu je začel čistiti Juda in Jeruzalem pred visokimi kraji, ašerami, izrezljanimi podobami in ulitimi podobami.',
        4: 'V njegovi prisotnosti so porušili Báalove oltarje in podobe, ki so bile visoko nad njimi, je posekal. Ašere, izrezljane podobe in ulite podobe je zdrobil na koščke in iz njih naredil prah in ga raztresel po grobovih tistih, ki so jim žrtvovali.',
        5: 'Kosti duhovnikov je sežgal na njihovih oltarjih ter očistil Juda in Jeruzalem.',
        6: 'Tako je storil v mestih Manáseja, Efrájima in Simeona, celo do Neftálija, z njihovimi motikami naokoli.',
        7: 'Ko je porušil oltarje in ašere in je rezane podobe poteptal v prah in posekal vse malike po vsej izraelski deželi, se je vrnil v Jeruzalem.',
        8: 'Torej v osemnajstem letu njegovega kraljevanja, ko je očistil deželo in hišo, je poslal Acaljájevega sina Šafána, voditelja mesta Maasejája in Joaházovega sina letopisca Joáha, da popravi hišo Gospoda, svojega Boga.',
        9: 'Ko so prišli k vélikemu duhovniku Hilkijáju so izročili denar, ki je bil prinesen v Božjo hišo, ki so ga zbrali Lévijevci, ki so varovali vrata, iz roke Manáseja, Efrájima in vsega Izraelovega preostanka in od vsega Juda in Benjamina in se vrnili v Jeruzalem.',
        10: 'Položili so ga v roko delavcev, ki so imeli nadzor nad Gospodovo hišo in ga izročili delavcem, ki so delali v Gospodovi hiši, da hišo popravijo in izboljšajo.',
        11: 'Izročila sta ga celo rokodelcem in graditeljem, da kupijo klesan kamen, les za vezi in da tlakujejo hiše, ki so jih Judovi kralji uničili.',
        12: 'Možje so zvesto opravljali delo in njihovi nadzorniki so bili Jahat in Obadjá, Lévijevca izmed Meraríjevih sinov; Zeharjá in Mešulám izmed Kehátovih sinov, da bi ga nadzirali in drugi izmed Lévijevcev, vsi, ki so vešči glasbenih instrumentov.',
        13: 'Bili so tudi nad nosilci bremen in bili so nadzorniki vseh teh, ki so na kakršen koli način opravljali delo. Izmed Lévijevcev so bili pisarji, častniki in vratarji.',
        14: 'Ko so jemali ven denar, ki je bil prinesen v Gospodovo hišo, je duhovnik Hilkijá našel knjigo Gospodove postave, ki je bila dana po Mojzesu.',
        15: 'Hilkijá je odgovoril in pisarju Šafánu rekel: »V Gospodovi hiši sem našel knjigo postave.« In Hilkijá je knjigo izročil Šafánu.',
        16: 'Šafán je knjigo odnesel h kralju in [poleg tega] kralju prinesel besedo, rekoč: »Vse, kar je bilo poverjeno tvojim služabnikom, so to storili.«',
        17: 'Skupaj so zbrali denar, ki je bil najden v Gospodovi hiši ter ga izročili v roko nadzornikov in delavcev.',
        18: 'Potem je pisar Šafán povedal kralju, rekoč: »Duhovnik Hilkijá mi je izročil knjigo.« In Šafán jo je bral pred kraljem.',
        19: 'Zgodilo se je, ko je kralj slišal besede postave, da je pretrgal svoja oblačila.',
        20: 'Kralj je ukazal Hilkijáju, Šafánovemu sinu Ahikámu, Mihajájevemu sinu Abdónu, pisarju Šafánu in kraljevemu služabniku Asajáju, rekoč:',
        21: '»Pojdite, vprašajte Gospoda zame in za tiste, ki so preostali v Izraelu in Judu, glede besed knjige, ki se je našla, kajti velik je Gospodov bes, ki je izlit na nas, ker se naši očetje niso držali Gospodove besede, da bi delali po vsem, kar je napisano v tej knjigi.«',
        22: 'Hilkijá in tisti, ki jih je kralj določil, so odšli k prerokinji Huldi, ženi Šalúma, Tikvájevega sina, Hasrájevega sina, varuha garderobe (torej prebivala je v Jeruzalemu, v drugem okraju) in ji prav tako govorili.',
        23: 'Odgovorila jim je: »Tako govori Gospod, Izraelov Bog: ›Povejte človeku, ki vas je poslal k meni:',
        24: '›Tako govori Gospod: ›Glejte, zlo bom privedel nad ta kraj in nad njegove prebivalce, celó vsa prekletstva, ki so zapisana v knjigi, ki so jo brali pred Judovim kraljem,',
        25: 'ker so me zapustili in zažigali kadilo drugim bogovom, da bi me lahko dražili do jeze z vsemi deli svojih rok, zato bo moj bes izlit na ta kraj in ne bo pogašen.',
        26: 'Kar se tiče Judovega kralja, ki vas je poslal, da poizveste od Gospoda, mu boste rekli takole: ›Tako govori Gospod, Izraelov Bog, glede besed, ki si jih slišal:',
        27: '›Ker je bilo tvoje srce nežno in si se ponižal pred Bogom, ko si slišal njegove besede zoper to mesto in zoper njegove prebivalce in se ponižuješ pred menoj in si pretrgal svoja oblačila in jokal pred menoj; celo tudi jaz sem te slišal,‹ govori Gospod.',
        28: '›Glej, zbral te bom k tvojim očetom in v miru boš zbran k svojemu grobu niti tvoje oči ne bodo videle vsega zla, ki ga bom privedel nad ta kraj in nad prebivalce istega.‹« Tako so kralju ponovno prinesli besedo.',
        29: 'Potem je kralj poslal in zbral skupaj vse starešine iz Juda in Jeruzalema.',
        30: 'Kraj je odšel gor v Gospodovo hišo in vsi Judovi možje, prebivalci Jeruzalema, duhovniki, Lévijevci in vse ljudstvo, veliki in mali, in na njihova ušesa je bral vse besede knjige zaveze, ki se je našla v Gospodovi hiši.',
        31: 'Kralj je stal na svojem mestu in sklenil zavezo pred Gospodom, da hodi za Gospodom in da se drži njegovih zapovedi, njegovih pričevanj in njegovih zapovedi z vsem svojim srcem in z vso svojo dušo, da izpolni besede zaveze, ki so zapisane v tej knjigi.',
        32: 'Vsem, ki so bili prisotni v Jeruzalemu in Benjaminu, je velel, da pristopijo k temu. Prebivalci Jeruzalema so storili glede na zavezo Boga, Boga svojih očetov.',
        33: 'Jošíja je odvzel vse ogabnosti iz vseh dežel, ki so pripadale Izraelovim otrokom in pripravil vse, ki so bili prisotni v Izraelu, da služijo, torej da služijo Gospodu, svojemu Bogu. In vse svoje dni se niso odvrnili od sledenja Gospodu, Bogu svojih očetov.',
    },
    35: {
        1: 'Poleg tega je Jošíja praznoval pasho Gospodu v Jeruzalemu. Na štirinajsti dan prvega meseca so zaklali pashalno jagnje.',
        2: 'Postavil je duhovnike po njihovih zadolžitvah in jih ohrabril, da služijo v Gospodovi hiši.',
        3: 'Lévijevcem, ki so učili ves Izrael, ki so bili sveti Gospodu, je rekel: »Sveto skrinjo postavite v hišo, ki jo je zgradil Salomon, Davidov sin, Izraelov kralj. Ta naj ne bo breme na vaših ramah. Služite torej Gospodu, svojemu Bogu in njegovemu ljudstvu Izraelu',
        4: 'in pripravite se po hišah svojih očetov, po svojih skupinah glede na pisanje Izraelovega kralja Davida in glede na pisanje njegovega sina Salomona.',
        5: 'Stojte na svetem kraju, glede na razdelitve družin očetov, vaših bratov [od] ljudstva, in glede na razdelitev družin Lévijevcev.',
        6: 'Tako zakoljite pashalno jagnje, se posvetite in pripravite svoje brate, da bodo lahko storili glede na Gospodovo besedo, po Mojzesovi roki.',
        7: 'Jošíja je dal ljudstvu od tropa jagnjeta in kozličke, vse za pashalne daritve, za vse, ki so bili prisotni, do številke trideset tisoč in tri tisoč bikcev. To je bilo od kraljevega imetja.',
        8: 'Njegovi princi so voljno dali ljudstvu, duhovnikom in Lévijevcem. Hilkijá, Zeharjá in Jehiél, voditelji Božje hiše, so dali duhovnikom za pashalne daritve dva tisoč in šeststo [glav] majhne živine in tristo volov.',
        9: 'Tudi Konanjá, Šemajá in Netanél, njegovi bratje in Hašabjá, Jeiél in Jozabád, vodje Lévijevcev, so dali Lévijevcem za pashalne daritve pet tisoč [glav] majhne živine in petsto volov.',
        10: 'Tako je bila služba pripravljena in duhovniki so stali na svojem kraju in Lévijevci po svojih skupinah, glede na kraljevo zapoved.',
        11: 'Zaklali so pashalno jagnje in duhovniki so poškropili kri iz njihovih rok, Lévijevci pa so jih odrli.',
        12: 'Odstranili so žgalne daritve, da bi jih lahko dali glede na oddelke družin ljudstva, da darujejo Gospodu, kakor je to zapisano v Mojzesovi knjigi. In tako so storili z voli.',
        13: 'Pashalno jagnje so pekli z ognjem, glede na odredbo. Toda ostale svete daritve so kuhali v loncih, v kotlih in v ponvah in jih naglo razdelili med vse ljudstvo.',
        14: 'Potem so pripravili zase in za duhovnike, ker so bili duhovniki, Aronovi sinovi, zaposleni pri darovanju žgalnih daritev in tolšče do noči, zato so Lévijevci pripravili zase in za duhovnike, Aronove sinove.',
        15: 'Pevci, Asáfovi sinovi, so bili na svojem mestu, glede na zapoved Davida, Asáfa, Hemána in kraljevega vidca Jedutúna. Vratarji so čakali pri vsakih velikih vratih. Niso mogli oditi od svoje službe, kajti njihovi bratje Lévijevci so pripravljali zanje.',
        16: 'Tako je bila vsa Gospodova služba pripravljena isti dan, da praznujejo pasho in da darujejo žgalne daritve na Gospodovem oltarju, glede na zapoved kralja Jošíja.',
        17: 'Izraelovi otroci, ki so bili prisotni, so ob tistem času sedem dni praznovali pasho in praznik nekvašenega kruha.',
        18: 'Nobene pashe ni bilo podobne tej, ki so jo praznovali v Izraelu, od dni preroka Samuela niti niso vsi Izraelovi kralji praznovali takšne pashe, kot so jo praznovali Jošíja, duhovniki, Lévijevci in ves Juda, Izrael in prebivalci Jeruzalema, ki so bili prisotni.',
        19: 'V osemnajstem letu kraljevanja Jošíja so praznovali to pasho.',
        20: 'Po vsem tem, ko je Jošíja pripravil tempelj, je prišel gor iz Egipta kralj Nehu, da se bojuje zoper Kárkemiš pri Evfratu. Jošíja je odšel ven zoper njega.',
        21: 'Toda ta je k njemu poslal predstavnike, rekoč: »Kaj imam opraviti s teboj, Judov kralj? Danes nisem prišel zoper tebe, temveč zoper hišo, s katero imam vojno, kajti Bog mi je zapovedal, da pohitim. Zadrži se pred vmešavanjem z Bogom, ki je z menoj, da te on ne uniči.«',
        22: 'Kljub temu Jošíja svojega obraza ni hotel obrniti od njega, temveč se je preoblekel, da bi se lahko boril z njim in ni prisluhnil besedam Nehuja iz Božjih ust in je šel, da se bojuje v dolini Megído.',
        23: 'Lokostrelci pa so zadeli kralja Jošíja in kralj je rekel svojim služabnikom: »Odpeljite me proč, kajti hudo sem ranjen.',
        24: 'Njegovi služabniki so ga torej vzeli iz tega bojnega voza in ga položili na drug bojni voz, ki ga je imel. Privedli so ga v Jeruzalem in umrl je in bil pokopan v enem izmed mavzolejev svojih očetov. Ves Juda in Jeruzalem je žaloval za Jošíjem.',
        25: 'Jeremija je žaloval za Jošíjem in vsi pevci in pevke so do tega dne v svojih žalostinkah govorili o Jošíju in jih naredili za odredbo v Izraelu. Glej, zapisane so v žalostinkah.',
        26: 'Torej preostala izmed Jošíjevih dejanj in njegova dobrota, glede na to, kar je bilo napisano v Gospodovi postavi',
        27: 'in njegova dejanja, prva in zadnja, glej, zapisana so v knjigi Izraelovih in Judovih kraljev.',
    },
    36: {
        1: 'Potem je ljudstvo dežele vzelo Jošíjevega sina Joaháza in ga v Jeruzalemu postavilo [za] kralja namesto njegovega očeta.',
        2: 'Joaház je bil star triindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval tri mesece.',
        3: 'Egiptovski kralj ga je odstavil v Jeruzalemu in deželo obsodil na sto talentov srebra in talent zlata.',
        4: 'Egiptovski kralj je postavil njegovega brata Eljakíma [za] kralja nad Judom in Jeruzalemom ter njegovo ime spremenil v Jojakím. Neho je vzel njegovega brata Joaháza in ga odvedel v Egipt.',
        5: 'Jojakím je bil star petindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljevati enajst let. Počel je to, kar je bilo zlo v očeh Gospoda, njegovega Boga.',
        6: 'Zoper njega je prišel gor babilonski kralj Nebukadnezar in ga zvezal v okove, da ga odvede v Babilon.',
        7: 'Nebukadnezar je v Babilon odnesel tudi posode Gospodove hiše in jih postavil v svoj tempelj v Babilonu.',
        8: 'Torej preostala izmed Jojakímovih dejanj in njegove ogabnosti, ki jih je storil in to, kar je bilo najdeno v njem, glej, ta so zapisana v knjigi Izraelovih in Judovih kraljev, in namesto njega je zakraljeval njegov sin Jojahín.',
        9: 'Jojahín je bil star osem let, ko je začel kraljevati in v Jeruzalemu je kraljeval tri mesece in deset dni. Počel je to, kar je bilo zlo v Gospodovih očeh.',
        10: 'Ko je minilo leto, je kralj Nebukadnezar poslal in ga privedel v Babilon, s čudovitimi posodami Gospodove hiše in je njegovega brata Sedekíja postavil [za] kralja nad Judom in Jeruzalemom.',
        11: 'Sedekíja je bil star enaindvajset let, ko je začel kraljevati in v Jeruzalemu je kraljeval enajst let.',
        12: 'Počel je to, kar je bilo zlo v očeh Gospoda, njegovega Boga in se ni ponižal pred prerokom Jeremijem, ki je govoril iz Gospodovih ust.',
        13: 'Uprl se je tudi zoper kralja Nebukadnezarja, ki ga je pripravil, da priseže pri Bogu. Toda otrdil je svoj vrat in zakrknil svoje srce pred obrnitvijo h Gospodu, Izraelovemu Bogu.',
        14: 'Poleg tega so se vse vodje izmed duhovnikov in ljudstva zelo pregrešili za vsemi ogabnostmi poganov in oskrunili Gospodovo hišo, ki jo je posvetil v Jeruzalemu.',
        15: 'Gospod, Bog njihovih očetov je pošiljal k njim po svojih poslancih, zgodaj vstajal in pošiljal, ker je imel sočutje do njegovega ljudstva in do njegovih prebivališč.',
        16: 'Toda zasmehovali so Božje poslance, prezirali njegove besede in zlorabljali njegove preroke, dokler ni zoper njegovo ljudstvo vstal Gospodov bes, dokler tam ni bilo zdravila.',
        17: 'Zato je nadnje privedel kralja Kaldejcev, ki je njihove mladeniče usmrtil z mečem v hiši njihovega svetišča in ni imel sočutja nad mladeničem ali mladenko, starcem ali tistim, ki je sklonjen zaradi starosti; vse jih je izročil v njegovo roko.',
        18: 'Vse posode Božje hiše, velike in majhne, zaklade Gospodove hiše in kraljeve zaklade in [zaklade] njegovih princev; vse te je prinesel v Babilon.',
        19: 'Zažgali so Božjo hišo, porušili jeruzalemsko obzidje, vse palače požgali z ognjem in uničili vse njegove čudovite posode.',
        20: 'Tiste, ki so pobegnili pred mečem, je odvedel v Babilon, kjer so bili služabniki njemu in njegovim sinovom do kraljevanja perzijskega kraljestva,',
        21: 'da izpolni Gospodovo besedo po Jeremijevih ustih, dokler se dežela ne naužije svojih šabat, kajti dokler leži zapuščena, praznuje šabate, da izpolni sedemdeset let.',
        22: 'Torej v prvem letu perzijskega kralja Kira, da bi se Gospodova beseda, govorjena po ustih Jeremija, lahko dovršila, je Gospod razvnel duha perzijskega kralja Kira, da je naredil razglas po vsem svojem kraljestvu in ga položil tudi v pisanje, rekoč:',
        23: '»Tako govori Kir, kralj Perzije: ›Vsa kraljestva zemlje je Gospod, Bog nebes, izročil meni in zadolžil me je, da mu zgradim hišo v Jeruzalemu, ki je v Judeji. Kdo je tukaj med vami izmed vsega njegovega ljudstva? Gospod, njegov Bog naj bo z njim in naj ta gre gor.‹«',
    },
}
